quests[10643] = { id = 10643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herolde des Schattenmondklans", description = "Seid Euch im Klaren, dass Zorus keinen Humor hat.\n\nGenug geredet. Zieht die Geisterbrille auf, damit Ihr die Orcgeister des Schattenmondklans, die sich in dieser Feste herumtreiben, sehen könnt. Habt keine Angst. Eigentlich sind wir die Eindringlinge hier. Dennoch müssen sie zerstört werden, denn ihre Zeit ist schon lange vorüber.\n\nZerstört die Herolde des Schattenmondklans, die in der Wildhammerfeste spuken, und kehrt dann zu mir zurück.", sourceObjective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 12 Herolde des Schattenmondklans tötet.", progress = "Wenn Ihr Eure Brille verliert, kann ich Euch eine neue herstellen.", completion = "Ihr sagt, Ihr habt die Geister zu Euch flüstern hören? Und sie sprachen über Teron Blutschatten?\n\n<Zorus schaudert.>\n\nJa... Ich kenne Teron Blutschatten. Oder besser gesagt kannte ihn. Er ist schon vor langer Zeit gestorben. Wovon können diese Geister wohl gesprochen haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[10644] = { id = 10644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teron Blutschatten - Geschichte und Mythos", description = "Es gibt unzählige Geschichten über das Leben von Teron Blutschatten, aber manche sind eben nur Geschichten. Wir wissen nicht, was mit Blutschatten passiert ist, nachdem er nach Draenor zurückgekehrt war.\n\nMit Sicherheit wissen wir nur, dass er schon einmal gestorben ist.\n\nIch habe gehört, wie die Späher von einem alten Orcgeist sprachen, der beim Altar der Schatten haust. Er befindet sich weit im Osten, hinter den Netherschwingenfeldern und jenseits des Netherschwingenpasses. Nehmt diese Geisterbrille und sucht diesen Orc. Er weiß sicher mehr über Blutschatten.", sourceObjective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr den uralten Schattenmondgeist findet.\n\nFalls Ihr Eure Geisterbrille verlieren solltet, kann Euch Zorus der Richter eine neue herstellen.\n\nBereitgestellter Gegenstand:", completion = "Blutschatten? Diesen Namen habe ich schon seit ewigen Zeiten nicht mehr gehört!\n\nNach dem Zweiten Krieg kehrte Blutschatten mit seinen Todesrittern hierher zurück. Als er nicht mit der Schrecklichkeit seiner neuen Form zurechtkam und ohne die Hilfe seines geliebten Anführers, Gul'dan, hilflos war, nahm Blutschatten sich das Leben.\n\nIch weiß nichts davon, dass er nun als Geist in diesen Weiten herumwandeln soll. Aber vielleicht kann ich das mit Eurer Hilfe herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10645] = { id = 10645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin Teron Blutschatten...", description = "Jetzt, da wir Blutschattens Gegenstände beisammen haben, fehlt nur noch ein letztes Teil im Puzzle: ein Wirt.\n\n<Die Lippen des uralten Schattenmondgeistes verziehen sich zu einem bösartigen Grinsen.>\n\nIhr habt doch nicht etwa das Märchen geglaubt, das ich Euch aufgetischt habe? Der Altar der Schatten ist mein Gefängnis. Ohne Eure Hilfe wäre ich bis in alle Ewigkeit hier gefangen geblieben. Jetzt werde ich Euren Körper übernehmen und Ihr werdet die, die mich gefangen haben, vernichten und das Band für immer zerreißen. Wenn Ihr ablehnt, sind wir beide bis ans Ende der Zeit hier gefangen.\n\nTeron Blutschatten wird frei sein!", sourceObjective = "Der uralte Schattenmondgeist hat Euch benutzt! Nun, da Ihr alle Gegenstände, die er wollte, gesammelt habt, hat er sich als Teron Blutschatten offenbart. Um von seinem Bann loszukommen, müsst Ihr seinen Willen erfüllen und Karsius den uralten Wächter töten.\n\nWenn Ihr erfolgreich wart, meldet Euch bei Zorus dem Richter in der Wildhammerfeste.", completion = "Was habt Ihr getan? DUMMKOPF!\n\nIhr müsst dieses Unrecht wieder gutmachen. Schließlich war es Euer Fehler. Nehmt einen dieser Helme. Sie sind mit der Macht der ewig brennenden Asche, die Ihr mir gebracht habt, erfüllt. Viel wichtiger ist jedoch, dass Ihr damit die Geister Schattenmonds sehen könnt, auch Teron Blutschatten.\n\nWenn Ihr ihn jemals findet, vernichtet ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[10646] = { id = 10646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidans Schüler", description = "Ihr habt bewiesen, dass Ihr guter Gesinnung seid, {name}. Bitte verzeiht mein Misstrauen, aber in dieser Welt sind die Dinge nicht so, wie sie scheinen.\n\nWenn Ihr bereit seid, werde ich Euch von Varedis erzählen.", sourceObjective = "Hört Euch Altruis' Geschichte an.", completion = "Jetzt kennt Ihr die Geschichte. Bleibt nur noch eine Sache zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10647] = { id = 10647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Uvuros, Geißel des Schattenmondtals", description = "Gesucht - TOT:\n\nUvuros, Geißel des Schattenmondtals.\n\nAuf Befehl des Oberanführers Or'barokh ist die Teufelsbestie zu töten, wenn sie angetroffen wird. Ferner ist die Mähne als Beweis von dem toten Leib abzutrennen. Bringt die feurige Mähne der Bestie zu Kriegsrufer Sardon Treuschnitt, wenn Ihr erfolgreich wart.\n\nUvuros wurde zuletzt bei der Hand von Gul'dan im Herzen des Schattenmondtals, östlich von Schattenmond, gesehen.", sourceObjective = "Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Sardon Treuschnitt in Schattenmond im Schattenmondtal.", progress = "Willst du die Belohnung kassieren, Mann?", completion = "Du bist echt der Brüller, was? Gut gemacht! Und du kriegst auch deine Belohnung. Is' doch Ehrensache...", sourceObjectiveStatus = "unverified-source-field" }
quests[10648] = { id = 10648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Uvuros, Geißel des Schattenmondtals", description = "Gesucht- TOT:\n\nUvuros, Geißel des Schattenmondtals.\n\nAuf Befehl von Than Yoregar ist die Teufelsbestie zu töten, wenn sie angetroffen wird. Ferner ist die Mähne als Beweis von dem toten Leib abzutrennen. Bringt die feurige Mähne der Bestie zu Kriegsrufer Bierschnut, wenn Ihr erfolgreich wart.\n\nUvuros wurde zuletzt bei der Hand von Gul'dan im Herzen des Schattenmondtals, nordöstlich der Wildhammerfeste, gesehen.", sourceObjective = "Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Bierschnut in der Wildhammerfeste im Schattenmondtal.", progress = "Ich hoffe, Ihr habt etwas Großartiges getan, Bursche. Ansonsten macht Euch vom Acker!", completion = "Hier ist Eure Belohnung. Gebt nicht alles auf einmal aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10649] = { id = 10649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der teuflischen Namen", description = "Ich finde es gut, dass Ihr vorhabt, Varedis und seine Anhänger aufzuhalten, aber Ihr habt keine Chance gegen ihn. Es sei denn, Ihr findet das Artefakt, das ihm seine Macht verliehen hat.\n\nDas Buch der teuflischen Namen soll sich im Besitz von Schwarzherz dem Hetzer befinden, der sich im Labyrinth von Auchindoun aufhält. Eure einzige Hoffnung, Varedis besiegen zu können, ruht auf diesem Buch.", sourceObjective = "Reist in das Schattenlabyrinth von Auchindoun und besorgt das Buch der teuflischen Namen von Schwarzherz dem Hetzer. Kehrt danach zu Altruis in Nagrand zurück.", progress = "Habt Ihr das Buch besorgt, {name}?", completion = "Ich konnte die Macht des Buches schon über Meilen hinweg spüren. Die Versuchung, es einfach zu behalten ist... sehr groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[10650] = { id = 10650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu den Aldor", description = "Dieses Buch... könnte meine Macht verzehnfachen... nein! Es würde meine Seele verderben, ich weiß es genau. Bringt es zurück zu denen, die Euch geschickt haben, {name}.\n\nIhr habt nun die Mittel, um Varedis aufzuhalten. Wartet, bis er sich mithilfe der Metamorphose in seiner dämonischen Form manifestiert. Genau in diesem Moment müsst Ihr das Buch in seiner Anwesenheit verbrennen. Nur so könnt Ihr ihn seiner Macht berauben.", sourceObjective = "Sprecht mit Exarch Onaala beim Altar der Sha'tar im Schattenmondtal.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ihr bringt diese Abscheulichkeit eines Buches an einen heiligen Ort? Ich hoffe, dass Ihr dafür eine gute Erklärung habt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10651] = { id = 10651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varedis muss aufgehalten werden", description = "Wir müssen dieses abscheuliche Artefakt zerstören, jedoch nicht, bevor wir damit Varedis seiner Mächte beraubt haben.\n\nDas Ausbildungsgelände der Ruinen von Karabor muss für alle Zeiten geschlossen werden. Dazu müsst Ihr nicht nur Varedis töten, sondern auch seine drei Nachtelfenmeister, die ihn unterstützen: Alandien, Theras und Netharel.\n\nStellt eine geeignete Truppe zusammen und kehrt zu den Ruinen von Karabor zurück. Befolgt Altruis' Anweisungen, um Varedis zu besiegen. Ich hoffe für uns alle, dass sie funktionieren.", sourceObjective = "Exarch Onaala möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Exarch Onaala zurück.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ausgezeichnete Arbeit, {name}! Euer Sieg über Varedis ist ein entscheidender Schritt in unserem Krieg gegen Illidan.\n\nIhr habt Euch nicht nur den Aldor, sondern gegenüber der gesamten Scherbenwelt als würdig erwiesen. Bitte gestattet mir, die Überreste dieses schrecklichen Buchs zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10652] = { id = 10652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Linien", description = "Es wurden alle Vorkehrungen getroffen, um Euch zum Versteck der Spione zu bringen. Sucht mich einfach auf, wenn Ihr bereit seid, und wir werden Euch auf den Weg schicken.", sourceObjective = "Sprecht mit Veronia, wenn Ihr bereit seid, zur Manaschmiede Coruu aufzubrechen. Meldet Euch dort bei Caledis Morgenhell.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Willkommen, {class}. Bemüht Euch, unsere Position nicht zu verraten.\n\nWenn Kaels Spießgesellen uns entdecken, leben wir nicht mehr lange.", sourceObjectiveStatus = "unverified-source-field" }
quests[10653] = { id = 10653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Male des Sargeras", description = "Inzwischen sollte Euch klar geworden sein, dass wir der Brennenden Legion und ihren Dienern feindlich gesonnen sind.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, dann bringt mir die Insignien der hochrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Die hochrangigsten Mitglieder der Legion findet Ihr im Nethersturm und im Schattenmondtal.", sourceObjective = "Bringt 10 Male des Sargeras zu Adyen dem Lichtwächter in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, {name}?", completion = "Sich den Dämonen der Brennenden Legion und den wahnsinnigen Kultisten, die sie verehren, zu stellen ist keine geringe Tat, {name}. Ihr habt viel Hingabe und Mut bewiesen. Macht so weiter, und Euer Ruf bei den Aldor wird weiter steigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10654] = { id = 10654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Male des Sargeras", progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, {name}? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können.", completion = "Beweist Euch weiterhin als würdig, {name}. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden." }
quests[10655] = { id = 10655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Male des Sargeras", progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Ihr beweist Euch weiterhin als würdig, {name}. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden." }
quests[10656] = { id = 10656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Sonnenzorns", description = "Ihr wisst vielleicht, dass die Seher mit Kael'thas Armeen im Krieg stehen. Kael betrachtet uns als Bedrohung für seinen Einfluss über die Blutelfen und hat immer wieder versucht, uns zu vernichten.\n\nWenn Ihr uns in der Schlacht gegen Kael'thas helfen wollt, gibt es viele Ziele, die Ihr angreifen könnt. Kaels hochrangigste Soldaten tragen die Siegel des Sonnenzorns, der ihren Rang angibt. Ihr findet sie überall im Nethersturm und im Schattenmondtal.", sourceObjective = "Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Los, {name}. Sprecht.", completion = "Kaels Armee des Sonnenzorns ist sehr gut ausgebildet. Ihr habt beeindruckende Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10657] = { id = 10657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie abblitzen!", description = "Wir sind nicht gerade sparsam mit dem Zephyriumkapazitorium umgegangen. Aber wie es scheint verfügen die Schuppenflügelschlangen im Messergrat östlich von hier über einen Blitzschlagatem und Blitzschlagdrüsen, die wir uns zu Nutze machen können.\n\nIch habe den Magnetsammler repolarisiert, sodass er die Blitzschläge absorbieren kann. Begebt Euch dorthin, schaltet es an und besorgt uns ein wenig billige Energie!", sourceObjective = "Benutzt die repolarisierte Magnetsphäre, um 25 Blitzschläge von Schuppenflügelschlangen abzufangen. Beschafft darüber hinaus 5 Blitzschlagdrüsen eines Schuppenflügels.", progress = "Der Trick dabei ist, die repolarisierte Magnetsphäre rechtzeitig abzuschalten, bevor Ihr gegrillt werdet.\n\nNatürlich müsst Ihr Euch dabei gut überlegen, wie vielen Schlangen Ihr gleichzeitig gegenübersteht.\n\nWo wir gerade davon sprechen, habt Ihr die Sphäre schon aufgeladen?", completion = "Jippieh, es hat geklappt! Ich war mir da ehrlich gesagt nicht so sicher... Ich habe eine Wahrscheinlichkeit von 23,72 Prozent berechnet, dass Ihr beim dritten Treffer implodiert.\n\n<Toshley grinst unschuldig.>\n\nJetzt wissen wir also, dass die Sphäre funktioniert. Es sollte also keine weiteren Probleme geben, den nötigen Saft für unser Zephyriumkapazitorium zu beschaffen. Natürlich nur, wenn ich noch mehr Freiwillige finde, die für mich dort hinaus gehen und sich brutzeln lassen.\n\nAber Ihr habt den Pionier für unsere Bemühungen gespielt und verdient eine Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[10658] = { id = 10658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Siegel des Sonnenzorns", progress = "Was habt Ihr in letzter Zeit für uns getan, {name}? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?", completion = "Ausgezeichnet! Das wird Kael'thas zeigen, dass unsere Macht nicht zu unterschätzen ist." }
quests[10659] = { id = 10659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Siegel des Sonnenzorns" }
quests[10660] = { id = 10660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welch merkwürdige Wesen...", description = "Ich möchte mehr über die merkwürdigen Reptilien, die bei den Lavaströmen des Schattenmondtals umherstreifen, erfahren. Ich habe noch nie zuvor Tiere gesehen, die der sengenden Hitze geschmolzener Lava widerstehen konnten!\n\nAußerhalb von Schattenmond, wo der Boden aufgerissen ist und die Lava durch die Risse tritt, findet Ihr die Teufelsfeuerdimetrodonten. Tötet sie und bringt mir ihre Milzen. Mit ihrer Hilfe kann ich eine erste Analyse ihres Feuerwiderstands durchführen.\n\nBeginnt Eure Suche im Südosten.", sourceObjective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt.", progress = "Milzen! Ich brauche Milzen!", completion = "<Forscher Tiorus nimmt die Milzen an sich und beginnt seine Untersuchung.>\n\nDas dürfte eine Weile dauern. Nehmt dies als Bezahlung für Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10661] = { id = 10661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demilziös!", description = "Habt Ihr jemals von Essen gehört, dass sich selbst kocht und für immer warm bleibt? Das wäre traumhaft!\n\nAber vielleicht muss es kein Traum bleiben! Außerhalb der Feste, in der Nähe der Lavabecken und Lavaströme, gibt es Kreaturen, die in der glühenden Hitze gedeihen. Man nennt sie Teufelsfeuerdimetrodonten.\n\nDie Zwerge hier haben mir gesagt, dass sie die leckersten Milzen aller Zeiten haben. Und das Beste ist, dass sie schon vorgekocht sind! Bringt mir ein paar dieser Milzen! Ich werde Euch gut bezahlen.\n\nBeginnt direkt östlich von hier mit Eurer Suche.", sourceObjective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt.", progress = "Milzen! Ich brauche Milzen!", completion = "<Gnomus reißt die Milzen hungrig an sich.>\n\nHier ist die versprochene Bezahlung. Ich rufe Euch, wenn ich noch mehr Milzen brauche.\n\nSo lecker... Ich würde fast meinen 'demilziös'!", sourceObjectiveStatus = "unverified-source-field" }
quests[10662] = { id = 10662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wanderschmied", description = "<Ordinn betrachtet seinen Versuch, das Metall zu schmieden, und schüttelt den Kopf.>\n\nMeine Fertigkeiten reichen dazu nicht aus, aber das soll nicht heißen, dass die Waffe für Euch nicht neu geschmiedet werden kann.\n\nEin talentierter Schmied namens David Wayne begleitete die Söhne Lothars nach Draenor, doch er beschloss, die Expedition zu verlassen. Heute lebt er in einem kleinen Lager auf einer Halbinsel östlich des Postens der Feuerschwingen in den Wäldern von Terokkar. Bringt diese Barren zu ihm und schaut, ob Ihr ihm beim Schmieden der Waffe helfen könnt.", sourceObjective = "Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar.", progress = "Was führt Euch hierher, {class}? Ich bekomme nicht viel Besuch.", completion = "Ordinn hat Euch damit zu mir geschickt?\n\n<Der Schmied untersucht die Barren.>\n\nEr hatte Recht. Der Großteil der Magie ist verschwunden, aber ich kann noch immer Spuren davon in dem Metall spüren. Mit ein wenig Arbeit und ein paar 'ausgefallenen' Materialien kann ich Euch ein mächtiges antidämonisches Schwert aus diesem Metall schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10663] = { id = 10663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wanderschmied", description = "<Der Orc betrachtet seinen Versuch, das Metall zu schmieden, und schüttelt den Kopf.>\n\nMeine Fertigkeiten reichen dazu nicht aus, aber das soll nicht heißen, dass die Waffe für Euch nicht neu geschmiedet werden kann.\n\nEin talentierter Schmied namens David Wayne begleitete die Söhne Lothars nach Draenor, doch er beschloss, die Expedition zu verlassen. Heute lebt er in einem kleinen Lager auf einer Halbinsel östlich des Postens der Feuerschwingen in den Wäldern von Terokkar. Bringt diese Barren zu ihm und schaut, ob er Euch beim Schmieden der Waffe helfen kann.", sourceObjective = "Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar.", progress = "Was führt Euch hierher, {class}? Ich bekomme nicht viel Besuch.", completion = "Ordinn hat Euch damit zu mir geschickt?\n\n<Der Schmied untersucht die Barren.>\n\nIch werde ehrlich mit Euch sein, {class}. Ich bin in einer Zeit großgeworfen, in der die Kooperation mit der Horde undenkbar war.\n\nIch bin nicht so blind, dass ich nicht sehen würde, dass wir keine gemeinsamen Feinde haben. Ich werde Euch helfen, die antidämonische Waffe umzuschmieden, aber es wird einiges an Arbeit bedürfen und ein paar 'ausgefallene' Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[10664] = { id = 10664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusätzliche Materialien", description = "Das Metall, das Ihr mir gebracht habt, reicht zwar weitestgehend aus, um die Klinge des Schwerts zu schmieden, aber ich benötige noch viele andere Dinge, um die übrigen Teile der Waffe herzustellen.\n\nWollen wir mal schauen... Mir fehlen ein Adamantitrahmen, ein wenig schweres Knotenhautleder und ein Dämonenschutztotem. Geübte Kunsthandwerker sollten die ersten beiden Materialien herstellen können. Das dritte bekommt Ihr nur bei dem Reagenzienverkäufer Fantei im Unteren Viertel in Shattrath. Er hält sich bei den anderen Händlern auf.", sourceObjective = "David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm einen Adamantitrahmen, 4 Stück schweres Knotenhautleder und ein Dämonenschutztotem bringt.", progress = "Habt Ihr die Materialien?", completion = "<Der Schmied nimmt Euch die Materialien ab und nickt zufrieden.>\n\nDie werden reichen. Der Rest der Materialien, die ich benötige, wird jedoch nicht so leicht zu bekommen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10665] = { id = 10665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch von der Mechanar", description = "Um das Metall, das Ihr mir gebracht habt, zu bearbeiten, brauche ich große Hitze - viel mehr, als eine normale Schmiede herstellen kann.\n\nIch werde eine zusätzliche Hitzequelle für die Schmiede brauchen. Nur wenige Dinge in der Scherbenwelt können diese Art von Wärmeenergie liefern.\n\nIn der Mechanar der Festung der Stürme werden Manazellen, in denen eine unglaubliche Menge an Energie gespeichert ist, hergestellt. Sucht eine überladene Manazelle in den Stapeln um Mechanolord Kapazitus herum und bringt sie zu mir.", sourceObjective = "David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm eine überladene Manazelle bringt.", progress = "Konntet Ihr eine Manazelle aus der Mechanar schmuggeln?", completion = "Sie ist sogar noch mächtiger, als ich erwartet habe! Mit so viel Energie könnte ich ein Dutzend Klingen schmieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10666] = { id = 10666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encyclopaedia Daemonica", description = "Um die Verzauberungen auf der Klinge wiederherzustellen, müssen mehrere Zaubersprüche auf Dämonisch gesprochen werden.\n\nDas habe ich während meiner Ausbildung leider nicht gelernt, aber es führt kein Weg daran vorbei. Es gibt ein Buch, das Encyclopaedia Daemonica genannt wird. Darin könnte ich die meisten Worte, die ich brauche, finden. Leider ist das Buch im Besitz eines mächtigen Hexenmeisters des Schattenrats.\n\nTief im Schattenlabyrinth von Auchindoun wird es von Großmeister Vorpil bewacht. Tut, was immer Ihr tun müsst, um das Buch zu besorgen, und bringt es zu mir.", sourceObjective = "Beschafft die Encyclopaedia Daemonica von Großmeister Vorpil und bringt sie zu David Wayne in Waynes Zuflucht.", progress = "Habt Ihr das Buch besorgt?", completion = "<David blättert die Seiten des Buchs durch und schaudert.>\n\nDas ist nichts, mit dem man spielen sollte, {name}. Sobald die Waffe fertig ist, werde ich es zerstören. Es gibt schon genug dämonische Macht in dieser Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10667] = { id = 10667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterweltlehm", description = "Der Rahmen, den Ihr mir gebracht habt, wird nicht ausreichen, um geschmolzenes Metall ohne zusätzliche Verstärkung zu halten. Der Rahmen kann mit einer seltenen Art von Erde abgekühlt und verdichtet werden, die ihm eine unnatürliche Stärke verleiht.\n\nDiese Erde ist als Unterweltlehm bekannt und gilt bei den Naga als äußerst wertvoll. Nur wenige von ihnen besitzen etwas davon und ich kenne nur eine Naga in der Scherbenwelt, die sie benutzt: Hydromantin Thespia, die in der Dampfkammer des Echsenkessels lebt.", sourceObjective = "Beschafft Euch ein Gefäß mit Unterweltlehm von Hydromant Thespia und bringt es zu David Wayne in Waynes Zuflucht.", progress = "Habt Ihr den Unterweltlehm bekommen?", completion = "Das sollte funktionieren. Ich hatte zwar auf etwas mehr gehofft, aber um ehrlich zu sein können wir uns glücklich schätzen, hier draußen überhaupt etwas davon in die Finger bekommen zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10668] = { id = 10668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Illidari", description = "Ich habe immer noch Respekt vor Illidan. Ohne ihn hätte ich nie meinen Pfad gefunden.\n\nDoch er ist nicht mehr der, der er einst war. Seine Seele wurde von Macht verderbt, sein Geist durch seine Niederlagen zerrissen. Ich habe geschworen, das, was aus ihm geworden ist, zu vernichten. Seine Schoßtierchen, die Illidari, sind genauso abscheulich wie die Dämonen der Brennenden Legion.\n\nAuch wenn sich sein Griff um die Scherbenwelt lockert, hat er immer noch weit reichenden Einfluss. Beweist mir, dass Ihr nicht auf seiner Seite steht, und tötet seinen Leutnant Lothros bei der Stätte der Illidari im Schattenmondtal.", sourceObjective = "Altruis der Leidende möchte, dass Ihr Lothros in der Stätte der Illidari im Schattenmondtal tötet.", completion = "Ihr gehört also nicht zu Illidan. Ihr seid einen Schritt näher daran, mein volles Vertrauen zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10669] = { id = 10669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen jede Chance", description = "Einige Dämonen schwören nur sich selbst die Treue. Ein wahrer Dämonenjäger sucht und vernichtet jedoch seine Beute ungeachtet ihrer Zugehörigkeit.\n\nDer Dämon Xeleth, ein Abtrünniger der Legion, wurde einst von den primitiven Sumpfkreaturen der Zangarmarschen als Gott verehrt. Als Draenor fast zerstört wurde, zog er sich in einen tiefen Schlaf unter dem Sumpflichtsee zurück. Findet das Portal beim See und steckt diesen Speer in den Boden.\n\nXeleth wird davon erwachen. Tötet ihn und beweist, dass Ihr ein Feind aller Dämonen seid.", sourceObjective = "Altruis der Leidende möchte, dass Ihr den magieerfüllten Silberspeer bei der Portalsicherung in der Nähe des Sumpflichtsees in den Zangarmarschen verwendet, um Xeleth zu wecken. Kehrt zu Altruis zurück, wenn Ihr den Dämon erlegt habt.", progress = "Ihr seid zurück. Ist Xeleth tot?", completion = "Gut gemacht, {name}. Er konnte sich also immer noch an den Tag erinnern, an dem ich den Speer in seinen Körper rammte? Das ist schon so lange her...", sourceObjectiveStatus = "unverified-source-field" }
quests[10670] = { id = 10670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Träne der Erdenmutter", description = "Die Verzauberungen des Schwerts müssen mit einem mächtigen Fokus gebunden werden, wie zum Beispiel einem Edelstein. Nur wenige Steine können eine so starke Magie in sich aufnehmen, ohne zu zerbersten, doch ich kenne einen.\n\nDer Edelstein, den wir brauchen, wird Träne der Erdenmutter genannt. Er ist ein mächtiges Artefakt, das sich in den Händen seiner Schöpfer, der Oger, befindet. Kriegshetzer O'mrogg, der den Stein im Augenblick besitzt, hat viele mächtige Verbündete in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Seid also vorsichtig, wenn Ihr die Träne besorgt, {name}.", sourceObjective = "Besorgt die Träne der Erdenmutter von Kriegshetzer O'mrogg und bringt sie zu David Wayne in Waynes Zuflucht.", progress = "Konntet Ihr den Edelstein O'mroggs Klauen entreißen?", completion = "<David Wayne hält den Edelstein gegen das Licht und bewundert ihn.>\n\nEr ist absolut makellos und genau das, was wir brauchen. Ein fehlerhafter Edelstein würde den Träger der Waffe in Gefahr bringen und die Magie gegen ihn richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10671] = { id = 10671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Pfund Geschnetzeltes", description = "{name}, ich habe noch eine andere Aufgabe für Euch. Einer der Eierköpfe möchte die bösartigen Fleischbestien untersuchen, die sich bei Razaans Landeplatz nördlich des Messergrats aufhalten.\n\nGenauer gesagt wollen sie das Fleisch der Fleischbestien dort untersuchen.\n\n<Dina verzieht angewidert das Gesicht.>\n\nAber sie wollen sich die Hände natürlich nicht schmutzig machen. Und sie wollen nur das astralisierte Fleisch, das sicher nicht alle haben.\n\nMeiner Meinung nach kann man als Bettler nicht wählerisch sein, aber was sollen wir schon machen?", sourceObjective = "Beschafft Euch 5 Einheiten astralisiertes Fleisch.", progress = "Habt Ihr mein Geschnetzeltes schon? Wie, das findet Ihr nicht lustig?", completion = "Das sollte genügen. Es stinkt fürchterlich, oder?\n\nIch hoffe, dass es Eure Mühen wert war... Ich bin nur froh, dass ich das Zeug nicht selber sammeln musste!", sourceObjectiveStatus = "unverified-source-field" }
quests[10672] = { id = 10672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ergibt echt keinen Sinn...", description = "Wir müssen diese Wesen weiter untersuchen.\n\nWeit im Osten, in der Nähe des riesigen Lavastroms unter den Ruinen von Baa'ri, könnt Ihr Arkanosteuereinheiten finden. Diese Steuerungen wurden von einem Genie namens Gnomus hergestellt. Ihr einziger Zweck ist, Lava mithilfe eines mechanischen Skorpions zu erforschen.\n\nEr hat schon vor langer Zeit den Verstand verloren. Jetzt interessiert er sich nur dafür, das heißeste Essen in der Geschichte der Gnomheit zu futtern.\n\n<Tiorus rollt mit den Augen.>\n\nIch möchte, dass Ihr die Steuereinheit benutzt, um die Dimetrodonten des Lavastroms für unsere weiteren Studien zu markieren.", sourceObjective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr zu dem Lavastrom in der Nähe der Ruinen von Baa'ri reist und die Arkanosteuereinheit benutzt, um einen Arkanoskorp zu steuern. Schwimmt mit dem Arkanoskorp durch die Lava und markiert 8 große Teufelsfeuerdimetrodonten.", completion = "Wir haben keine Zeit zu verschwenden. Ich habe die markierten Dimetrodonten beobachtet und herausgefunden, dass sie alle einem riesigen, nein, GIGANTISCHEN Dimetrodon namens Teufelsflosse dem Großen unterstellt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10673] = { id = 10673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsflosse der Große", description = "Gnomus weiß von dem riesigen Dimetrodon und will es aufessen! Er muss von irgendwoher erfahren haben, was ich durch sein Arkanoskorp gesehen habe. Nun, wir haben keine Zeit für Erklärungen. Er ist verrückt, und diese Verrücktheit könnte uns das kosten, was einem feuerfesten Anzug am nächsten kommt.\n\nKehrt zurück zum Lavastrom in der Nähe von Baa'ri und findet Teufelsflosse den Großen. Bringt mir seinen Balg!\n\nVersucht nicht mit mir zu diskutieren, {name}. Darüber bin ich längst hinaus.", sourceObjective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr Teufelsflosse den Großen tötet und Teufelsflosses Balg beschafft.", progress = "Kommt in die Gänge! Der Appetit dieses Gnoms kennt keine Grenzen!", completion = "Endlich bin ich vollkommen vor der Lava geschützt! Natürlich könnt auch Ihr etwas von dieser Technologie abhaben, {name}. Ihr habt es Euch verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10674] = { id = 10674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht der Phantasie einfangen", description = "Die Astralen der Razaani bei Razaans Landeplatz im Norden spielen mit einer interessanten Technologie herum.\n\nIch bin mir sicher, dass sie nichts dagegen hätten, wenn Ihr diese Falle benutzen würdet, um ein paar ihrer kleinen, rosafarbenen, schwebenden Lichtkugeln zu sammeln. Wahrscheinlich sind sie ohnehin nur Dekoration.\n\nDie Falle hat eine ganz spezielle Eigenschaft. Wenn sie geöffnet wird, sollte sie eine der schwebenden Kugel anziehen. Natürlich wird sie auch die Aufmerksamkeit der Razaani auf Euch lenken.", sourceObjective = "Benutzt die Lichtfalle, um 15 Lichtkugeln der Razaani zu fangen.", progress = "Ich nehme an, dass Ihr die Lichtkugeln bei Razaans Landung schon besorgt habt, wenn Ihr Zeit habt, hier mit mir zu plaudern. Ich würde sie wirklich gerne untersuchen und herausfinden, was die Astralen damit vorhaben.", completion = "He! Wartet mal!!\n\nDas sieht nicht gut aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[10675] = { id = 10675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gnom kennt kein Erbarmen!", description = "<Toshley erbleicht.>\n\nDiese Kugeln bestehen sowohl aus Netherenergie als auch aus Seelen! Sogar Gnomseelen sind dabei!\n\nWie können sie es wagen! Waren sie es vielleicht, die unsere Leute, die auf dem Weg nach Norden waren, getötet haben?!\n\n{name}, Ihr müsst dem ein Ende setzen und das geht nur, wenn Ihr ihren Anführer, Nexusprinz Razaan, ausschaltet.\n\nIhr müsst ihn jedoch aus seinem Versteck herauslocken. Ich schätze, dass Ihr das erreichen könnt, indem Ihr möglichst viele seiner Astralen der Razaani tötet.\n\nBringt mir seine Seelensammlung. Ich bin mir sicher, dass er eine hat.", sourceObjective = "Beschafft Euch die Seelensammlung.", progress = "Habt Ihr diesen Dreckskerl Razaan schon erledigt?", completion = "Das geschieht ihm ganz Recht! Vielen Dank, dass Ihr dieser makaberen Mischung aus Magie und Technologie ein Ende bereitet habt.\n\nAls wahrer Held der Gnome überall auf dieser Welt, lasse ich Euch nun die höchste unserer Ehren zukommen... ein paar Stromwandler und Eure Wahl aus diesen Dingen hier!\n\nIch weiß, dass Ihr sie gut einsetzen werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[10676] = { id = 10676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bann der Illidari", description = "<David sammelt seine Schmiedeausrüstung zusammen.>\n\nIhr habt alles, was ich zum Schmieden einer antidämonischen Klinge brauche. Eure harte Arbeit und Euer Einsatz soll belohnt werden.\n\nEs ist an der Zeit, die Klinge zu schmieden.", sourceObjective = "Wartet, bis David Wayne das Schwert für Euch fertig geschmiedet hat.", completion = "<David wischt sich den Schweiß von der Braue.>\n\nDer größte Teil der Arbeit ist getan. Um die Magie jedoch zum Leben zu erwecken, muss das Schwert erst gehärtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10677] = { id = 10677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zweite Gang...", description = "Ich erinnere mich, dass ich östlich der Hand von Gul'dan, in der Nähe der Lavaströme um die Ruinen von Baa'ri herum größere Dimetrodonten gesehen habe. Ich möchte, dass Ihr mir einen überentwickelten Teufelsfeuermuskelmagen von den Kreaturen in dieser Gegend besorgt. Ihr müsst wahrscheinlich mehrere erlegen, bevor Ihr einen solchen Muskelmagen findet. Bleibt immer schön am Ball! Einer von ihnen hat meine nächste Mahlzeit bei sich!", sourceObjective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr einen überentwickelten Teufelsfeuermuskelmagen besorgt.", progress = "Tagesmenü: Muskelmagen.", completion = "Das ist fantastisch! Aber ich habe gerade unglaubliche Nachrichten erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10678] = { id = 10678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Hauptgericht!", description = "Ich werde mich kurz fassen. Ich arbeitete einst mit einem Blutelfen namens Tiorus zusammen. Meine Partnerschaft zu Tiorus brach ab, als ich mich dem Leben als Gourmet zugewandt habe. Er beschloss, unsere Forschungen mit MEINEN Erfindungen auf eigene Faust weiterzuführen. Wie auch immer, er hat ein paar seiner Hordendummköpfe meine Arkanoskorpfühler bei den Ruinen von Baa'ri benutzen lassen und dabei den Vater aller Dimetrodonten entdeckt!\n\nIch möchte, dass Ihr vor ihm dorthin gelangt und das Dimetrodon Teufelsflosse tötet. Bringt mir seinen Balg!\n\nBeeilt Euch!", sourceObjective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr Teufelsflosses Balg besorgt.", progress = "Tagesmenü: Teufelsflosses Balg", completion = "Ich brauche jetzt etwas Zeit für mich, {name}. Vielen Dank für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[10679] = { id = 10679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe härten", description = "Die Klinge ist fast fertig!\n\nMan kann beinahe schon fühlen, wie die Magie im Stahl zusammenfließt. Aber eine Sache ist noch zu tun.\n\nIhr müsst die geschmiedete Klinge zu den Siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan im Schattenmondtal bringen und das Schwert in den Lavabecken härten. Kehrt zurück, wenn Ihr den Stahl gehärtet habt.", sourceObjective = "Reist zu den Siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan und härtet die geschmiedete Klinge des Illidaribanns in den Lavabecken. Kehrt dann mit der gehärteten Klinge des Illidaribanns zu David Wayne in Waynes Zuflucht zurück.", progress = "Habt Ihr das Schwert in der Lava der Hand von Gul'dan gehärtet?", completion = "Gut gemacht!\n\n<Der Schmied untersucht die Klinge sehr genau.>\n\nIch würde sagen, dass sie deutlich besser ist, als die grobe Waffe der Legion, mit der wir angefangen haben. Diese Klinge wird nicht nur die Dämonen der Illidari erschlagen, sondern auch die Diener der Legion vernichten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10680] = { id = 10680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand von Gul'dan", description = "Die Elemente brauchen Eure Hilfe, {race}! Das Schattenmondtal wurde von unaussprechlichen Schrecken heimgesucht. Bis zum heutigen Tag leiden die Geister. Viele sind wütend und wollen nicht mit dem Irdenen Ring in Verbindung treten.\n\nHelft dieser Welt zu heilen, Freund.\n\nNordöstlich der Wildhammerfeste gibt es einen Ort, der als der Altar der Verdammnis bekannt ist. Begebt Euch dorthin und sprecht mit Erdheiler Torlok.", sourceObjective = "Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal.", completion = "Es ist gut, dass Ihr gekommen seid, {race}. Wir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10681] = { id = 10681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand von Gul'dan", description = "Die Elemente brauchen Eure Hilfe, {race}! Das Schattenmondtal wurde von unaussprechlichen Schrecken heimgesucht. Bis zum heutigen Tag leiden die Geister. Viele sind wütend und wollen nicht mit dem Irdenen Ring in Verbindung treten.\n\nHelft dieser Welt zu heilen, Freund.\n\nSüdöstlich von Schattenmond, im Herzen des Schattenmondtals, gibt es einen Ort, der als der Altar der Verdammnis bekannt ist. Begebt Euch dorthin und sprecht mit Erdheiler Torlok.", sourceObjective = "Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal.", completion = "Es ist gut, dass Ihr gekommen seid, {race}. Wir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10682] = { id = 10682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zu verhandeln...", description = "Als wir hier im Ruuanwald ankamen, hielten sich die Wyrmkultisten nur im Pechschwingenkoven, der sich jenseits des Tunnels im Westen befindet, auf. Doch nun rücken sie immer näher an uns heran.\n\nIhr müsst den Aufseher der Wyrmkultisten finden. Es ist bekannt, dass er regelmäßige Kontrollgänge zwischen den verschiedenen Lagern hier im Ruuanwald durchführt.\n\nVerhandelt mit ihm. Lasst ihn wissen, dass wir kompromissbereit sind, jedoch auf keinen Fall zu dem Abschlachten der Wildtiere oder dem Fällen von Bäumen beitragen oder es tolerieren werden.", sourceObjective = "Verhandelt mit Aufseher Nuaar.", completion = "WAS?! Sie haben Euch fortgeschickt und unser Angebot ausgeschlagen?\n\nDas ist empörend! Wir sind in Frieden zu ihnen gekommen und sie schicken Euch weg, ohne auch nur zu versuchen, einen Kompromiss zu finden?\n\nNun, das wird Folgen haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10683] = { id = 10683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrifttafeln von Baa'ri", description = "Die Zerschlagenen der Aschenzungen wurden von Illidan beauftragt, in den Ruinen von Baa'ri weit im Norden Ausgrabungen durchzuführen. Sicher suchen sie nach Draeneiartefakten. Baa'ri verfügte über viele Relikte von Baa'ri, bevor Gul'dan die Stadt unter einer vulkanischen Explosion begrub. Wir müssen diese Chance nutzen, um an die Schrifttafeln von Baa'ri zu kommen. Dieser alte Text soll angeblich die Geheimnisse des Tempels von Karabor, der heute als Schwarzer Tempel bekannt ist, enthalten.", sourceObjective = "Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr 12 Schrifttafeln von Baa'ri vom Boden und von den Arbeitern der Aschenzungen in den Ruinen von Baa'ri sammelt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Schrifttafeln schon gefunden, {name}?", completion = "Die Schrifttafeln von Baa'ri! Ja, die werden uns sehr wichtige Informationen liefern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10684] = { id = 10684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronu der Älteste", description = "Laut den Schrifttafeln wurde in Baa'ri ein Artefakt, das als Medaillon der heiligen Stimme bekannt ist, aufbewahrt. Nur die höchstrangigen Draeneipriester durften es tragen, da es uneingeschränkten Zugang zum Tempel von Karabor bot.\n\nWir müssen herausfinden, ob die Aschenzungen das Medaillon schon gefunden haben. Seine Macht wäre uns eine große Hilfe im Kampf gegen Illidan.\n\nAkamas Leutnant in Baa'ri, Oronu der Älteste, erhält täglich schriftliche Befehle von Akama. Besorgt sie Euch und bringt sie mir.", sourceObjective = "Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr die Befehle von Akama von Oronu dem Ältesten in den Ruinen von Baa'ri besorgt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Gibt es schon Neuigkeiten, {name}? Wir haben nicht viel Zeit.", completion = "Akamas Handschrift... wollen wir mal sehen, was wir daraus erfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10685] = { id = 10685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderber der Aschenzungen", description = "Laut Akamas Brief wurden vier Teile des Medaillons ausgegraben und den Verderbern der Aschenzungen übergeben. Diese gefürchteten Zerschlagenen waren einst mächtige Schamanen, die nun die Elemente schänden, die sie einst verehrten.\n\nHaalum, der Verderber der Luft, befindet sich bei den Netherschwingenklippen. Eykenen und Uylaru, die Verderber der Erde und des Feuers, wurden zuletzt bei den Teufelsgruben in der Nähe der Hand des Gul'dan gesehen. Lakaan, der Verderber des Wassers, soll sich in der Nähe der Echsennarbe aufhalten.\n\nFindet sie und besorgt Euch die Medaillonfragmente von ihnen.", sourceObjective = "Beschafft die vier Medaillonfragmente von Haalum, Eykenen, Lakaan und Uylaru und kehrt danach zu Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal zurück.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die vier Fragmente des Medaillons, {name}?", completion = "Ja! Die vier Fragmente des Medaillons. Und nun setzt sie zusammen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10686] = { id = 10686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kerker des Wächters", description = "Die Fragmente, die Ihr besorgt habt, sind nur eine Hälfte des Amuletts. Der Anführer der Aschenzungen, Akama, muss die andere Hälfte haben.\n\nIch wage es fast nicht, Euch darum zu bitten, da Akama sowohl böse als auch gerissen ist.\n\nEr und die Todeshörigen der Aschenzungen – die bösartigsten und grausamsten der Zerschlagenen – sollen irgendwo im Kerker des Wächters eine Folterkammer betreiben.\n\nIch möchte, dass Ihr dieses gefürchtete Gefängnis findet und Akamas Aufenthaltsort bestimmt. Sein Stellvertreter vor Ort ist ein Zerschlagener namens Sanoru. Befragt ihn, wenn Ihr müsst.", sourceObjective = "Arkanist Thelis möchte, dass Ihr den Kerker des Wächters südlich der Ruinen von Baa'ri betretet und Sanoru über Akamas Aufenthaltsort befragt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Wir haben Euch erwartet, {name}. Akama sagte, dass Ihr früher oder später kommen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10687] = { id = 10687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildungsgelände von Karabor", description = "Unsere Späher haben uns von einem massiven Zufluss von Blutelfenrekruten des Sonnenzorns in den Ruinen von Karabor berichtet. Normalerweise würden wir darin eine rein militärische Bedrohung sehen, doch wir glauben, dass hier noch mehr im Argen liegt.\n\nDie Beschreibungen ihrer Kleidung und ihres Kampfstils klingen verdächtig nach Illidan selbst. Ich will mich nicht ohne handfeste Beweise beunruhigen, daher möchte ich Euch bitten, dorthin zu gehen und mir ihre Waffen zu bringen. Dann werden wir sehen, ob meine Befürchtungen unbegründet sind oder nicht.", sourceObjective = "Larissa Sonnenhieb beim Sanktum der Sterne möchte, dass Ihr 8 Gleven des Sonnenzorns von den Bittstellern der Dämonenjäger und den Initianden der Dämonenjäger in den Ruinen von Karabor, nordöstlich des Sanktums der Sterne, beschafft.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Aufgabe, mit der ich Euch betraut habe, erfüllt, {name}?", completion = "Wollen wir uns diese Waffen einmal genauer ansehen, {name}. Hmmm... das ist ziemlich beunruhigend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10688] = { id = 10688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine notwendige Ablenkung", description = "Die Waffen sind echt, wie wir befürchtet haben. Illidan bildet in den Ruinen von Karabor Dämonenjäger aus. Das müssen wir verhindern.\n\nLasst Euch nicht von dem Namen täuschen, {name}. Sie werden ihre Macht genauso oft gegen uns einsetzen, wie gegen Dämonen.\n\nIhre Hexenmeister beschwören und unterwerfen Dämonen im Rahmen der Ausbildung der Initiierten. Ein Grubenlord namens Azaloth hat sich in der Ausbildung als zu mächtig erwiesen und wird nun unter Verschluss gehalten. Findet einen Weg, ihn frei zu lassen und auf seine Kerkermeister zu hetzen. Das sollte uns die nötige Zeit verschaffen.", sourceObjective = "Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor zurückkehrt und Azaloth auf seine Kerkermeister hetzt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Das sollte uns genug Zeit verschaffen... hoffentlich reicht sie aus, um weitere Informationen zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[10689] = { id = 10689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altruis", description = "Heutzutage trifft man nur noch selten auf Dämonenjäger. Ihr eigenes Volk begegnet ihnen mit Argwohn. Und noch seltener findet man einen Dämonenjäger, der nicht im Bund mit Illidan steht.\n\nGerüchten zufolge soll ein solches Wesen hier in der Scherbenwelt leben. Sein Name ist Altruis. Er hasst alle Dämonen mit Leidenschaft und wird uns helfen, wenn Ihr ihn davon überzeugen könnt, dass wir auf seiner Seite stehen.\n\nGeht in den Westen Nagrands und sucht ihn. Vielleicht ist er bereit, etwas mehr über diese neuen Ausbildungsgelände für Dämonenjäger zu erzählen.", sourceObjective = "Reist in den Westen Nagrands und sucht Altruis den Leider.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ihr habt einen langen Weg hinter Euch, Fremder. Ich bin überrascht, dass derjenige, der Euch zu mir geschickt hat, von mir gehört hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10690] = { id = 10690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhlenmutter", description = "GESUCHT!\n\nRema, die Mutter und wichtigste Verteidigerin des Zackengrats südlich der Donnerfeste.\n\nIhr findet sie, indem Ihr das Dorf Richtung Osten verlasst und die Brücke über die Blutschlägerklamm überquert. Sie versteckt sich im Tunnel am südlichen Ende des Grats.\n\nKehrt mit den Nachrichten über Ihr Ableben zu Kommandant Himmelsschatten in Sylvanaar zurück.", sourceObjective = "Tötet Rema.", completion = "Unglaublich. Habt Ihr Rema ganz allein getötet?\n\nSo wie Ihr ausseht, glaube ich das. Wisst Ihr, ein starker {class} wie Ihr wäre uns hier eine große Hilfe. Besonders bei den ständigen Problemen, die wir mit den Ogern haben, könnten wir Euch brauchen. Setzt Euch mit mir in Verbindung, wenn Ihr Interesse habt.\n\nDas Kopfgeld, das auf dem Anschlag versprochen wurde, habt Ihr Euch jedenfalls verdient.\n\nBitte, wählt Euch etwas aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10691] = { id = 10691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu den Sehern", description = "Dieses Buch... könnte meine Macht verzehnfachen... Nein! Es würde meine Seele verderben, ich weiß es genau. Bringt es zurück zu denen, die Euch hierher geschickt haben, {name}.\n\nIhr habt nun die Mittel, um Varedis aufzuhalten. Wartet, bis er sich mithilfe der Metamorphose in seiner dämonischen Form manifestiert. Genau in diesem Moment müsst Ihr das Buch in seiner Anwesenheit verbrennen. Nur so könnt Ihr ihn seiner Macht berauben.", sourceObjective = "Sprecht mit Larissa Sonnenhieb beim Sanktum der Sterne im Schattenmondtal.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Viele würden für das Buch, das Ihr bei Euch tragt, einen hohen Preis bezahlen. Es ist eine Schande, dass wir es zerstören müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10692] = { id = 10692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varedis muss aufgehalten werden", description = "Wir müssen dieses abscheuliche Artefakt zerstören, jedoch nicht, bevor wir damit Varedis seiner Mächte beraubt haben.\n\nWir müssen diese Akademie von Illidanimitatoren auslöschen. Dazu müsst Ihr nicht nur Varedis töten, sondern auch seine drei Nachtelfenmeister, die ihn unterstützen: Alandien, Theras und Netharel.\n\nStellt eine geeignete Truppe zusammen und kehrt zu den Ruinen von Karabor zurück. Befolgt Altruis' Anweisungen, um Varedis zu besiegen. Ich hoffe für uns alle, dass sie funktionieren. Wenn nicht... war schön, Euch kennengelernt zu haben.", sourceObjective = "Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Larissa Sonnenhieb zurück.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ausgezeichnete Arbeit, {name}! Euer Sieg über Varedis ist ein entscheidender Schritt in unserem Krieg gegen Illidan.\n\nNach dieser Tat wird euer Name sicher die Runde machen.\n\nBitte erlaubt mir, die Überreste des Buchs der teuflischen Namen an mich zu nehmen. Ich werde dafür sorgen, dass es ordnungsgemäß... entsorgt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10693] = { id = 10693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen" }
