quests[10700] = { id = 10700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen" }
quests[10701] = { id = 10701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherbrock zerschmettern", description = "An alle, denen an einer rechtzeitigen Fertigstellung der X-52 Netherrakete gelegen ist:\n\nDer König der hiesigen Bergriesen, Netherbrock, terrorisiert die Schwindenden Weiten! Er behindert Unternehmungen am gesamten südlichen Rand der Insel!\n\nSchließt Euch mit ein paar Freunden zusammen und erledigt ihn! Kehrt dann zu mir hier in Area 52 zurück.\n\nRaketenchef Doppeldecker", sourceObjective = "Tötet Netherbrock und meldet Euch danach bei Raketenchef Doppeldecker in Area 52 im Nethersturm.", completion = "Oh! Oh... Ihr habt Netherbrock erledigt. Das sind gute Nachrichten!\n\nJetzt, da dieser lästige Bergriese von der Bildfläche verschwunden ist, können wir die Rohstoffe der Schwindenden Weiten leichter ausbeut... äh, verwalten.\n\nIch bin froh, dass diese armen, unschuldigen Elementare da unten jetzt nicht mehr von ihm zerquetscht werden.\n\nWie kann ich Euch je dafür entlohnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10702] = { id = 10702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Routinearbeiten", description = "Alle Streitkräfte der Horde in dieser Gegend sind damit beschäftigt, die Angriffe der Brennenden Legion abzuwehren. Wir haben daher niemanden, der uns die kleinen Routinearbeiten abnimmt.\n\nUnsere Versorgungskarawanen werden regelmäßig von den Wildtieren der Region bedroht. Wir können uns keine 15 Fuß von der Straße entfernen, ohne einer Schimäre, einem Teufelseber oder einem abnormal großen Skorpion in die Fänge zu laufen.\n\nGeht dort hinaus und befreit das Schattenmondtal von seinen sadistischen Wildtieren! Erschlagt sie einfach alle!", sourceObjective = "Oberanführer Or'barokh in Schattenmond im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.\n\nDazu gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig.", completion = "Fantastisch! Wenn ich noch mehr Routinearbeiten zu erledigen habe, komme ich auf Euch zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[10703] = { id = 10703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zieht Eure Knieschoner an...", description = "Es ist an der Zeit, sich im Schlamm zu wälzen und dreckig zu machen. Was habt Ihr denn erwartet? Man muss schließlich laufen lernen, bevor man krabbelt, oder nich'? Ähem, anders 'rum...\n\nEgal, wir haben jedenfalls alle Hände voll mit dem Müll zu tun, mit dem uns die Legion bewirft. Daher wird Euch die Ehre zuteil, die durchgeknallten Wildtiere des Schattenmondtals zu erlegen.\n\nSchnappt Euch Schwert, Stab oder was auch immer Euch glücklich macht, und tötet so viele Wildtiere, wie Ihr könnt. So halten wir den Weg für unsere Versorgungskarawanen frei.", sourceObjective = "Than Yoregar in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.\n\nDarunter gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig.", completion = "Jep, gute Arbeit! Hier habt Ihr ein wenig Bares für Eure Mühen. Wenn ich noch mehr Drecksarbeit zu erledigen habe, weiß ich ja, wen ich rufen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[10704] = { id = 10704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man in Arkatraz einbricht", description = "In dem Kristall von Ata'mal, den Ihr uns gebracht habt, war eine Nachricht versteckt. Nexusprinz Haramad hat uns dadurch wichtige Informationen für unsere Vorgehensweise gegen die Festung der Stürme zukommen lassen.\n\nEr berichtet, dass es einen zweiteiligen Schlüssel gibt, mit dem man den Satellit Arkatraz der Festung aufschließen kann.\n\nDie eine Hälfte des Schlüssels befindet sich im Besitz eines Urtums namens Warpzweig in der Botanika. Der zweite Teil wird von Panthaleon dem Kalkulator in der Mechanar bewacht.\n\nBringt mir beide Fragmente, damit ich den Schlüssel zur Arkatraz zusammensetzen kann.", sourceObjective = "A'dal bittet Euch, das obere und das untere Fragment des Schlüssels zur Arkatraz zu besorgen. Bringt beide Fragmente zu ihm zurück, damit er sie für Euch zum Schlüssel zur Arkatraz zusammenfügen kann.", progress = "<A'dals Stimme summt melodisch in Eurem Geist.>\n\nIhr seid zurück. Habt Ihr die beiden Fragmente des Schlüssels zur Arkatraz bei Euch?", completion = "Ich bin beeindruckt, {name}, auch wenn ich von dem Helden, der den Kristall von Ata'mal zurückgebracht hat, nichts anderes erwartet habe.\n\nGebt mir die Fragmente, damit ich sie zu ihrer endgültigen Form zusammenfügen kann. Dann werdet Ihr Zugang zur Arkatraz haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10705] = { id = 10705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seher Udalo", description = "Ich hoffe, Ihr seid nicht schockiert, wenn ich Euch verrate, dass die Teile des Medaillons von Karabor, die Ihr von meinen Dienern beschafft habt, nichts als Nachbauten sind.\n\n<Akama zeigt Euch ein identisches Medaillon, das auf seiner Handfläche liegt.>\n\nMeine Todeshörigen haben dieses Geheimnis so lange wie möglich vor Illidan bewahrt. Dennoch fehlt uns noch das letzte Stück.\n\nSeher Udalo erschien mir in meinen Träumen und sagte mir, dass er das letzte Stück gefunden habe. Er wird jedoch von Kael'thas auf der Arkatraz in der Festung der Stürme gefangen gehalten. Sucht ihn und findet heraus, was er weiß.", sourceObjective = "Sucht Seher Udalo in der Arkatraz in der Festung der Stürme.", completion = "Der Seher der Aschenzungen ist schon lange tot. Als Ihr Euch über seinen Körper beugt, erkennt Ihr, dass auf dem Boden etwas geschrieben steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10706] = { id = 10706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mysteriöses Omen", description = "Bevor er starb, hat Udalo noch ein einzelnes Wort auf den Boden unter sich geschrieben. Die Schrift ist kaum lesbar, aber Ihr erkennt das Wort 'Ata'mal'.\n\nVielleicht versteht Akama die Nachricht seines Bruders.", sourceObjective = "Kehrt zu Akama im Kerker des Wächters im Schattenmondtal zurück.", completion = "Ja... natürlich! Jetzt wird alles klar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10707] = { id = 10707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse von Ata'mal", description = "Wir haben herausgefunden, dass die Höllenorcs unter Illidans Kommando bei der Terrasse von Ata'mal einen Kristall von Ata'mal, der als Herz des Zorns bekannt ist, aufbewahren. Sie verschleiern seine Präsenz mit einer dunklen Magie, um ihn vor den Sha'tar zu verstecken.\n\nKämpft Euch zur Terrasse von Ata'mal außerhalb des Schwarzen Tempels durch und blickt zum Himmel. Schattenfürst Todesklage kreist außerhalb Eurer Reichweite um die Terrasse herum. Ihr müsst ihn und seine Hexenmeister töten, bevor Ihr an den Kristall kommt.\n\nEs wird nicht einfach werden, {name}. Ich wünsche Euch Glück.", sourceObjective = "Begebt Euch zur Spitze der Terrasse von Ata'mal im Schattenmondtal und beschafft das Herz des Zorns. Kehrt danach zu Akama beim Kerker des Wächters im Schattenmondtal zurück.", progress = "Ihr seid zurück, {name}.", completion = "Der Kristall! Seine Macht... in meinen Händen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10708] = { id = 10708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akamas Versprechen", description = "<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, {name}. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.", sourceObjective = "Bringt das Medaillon von Karabor zu A'dal in Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[10709] = { id = 10709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenführung", description = "Ihr kommt also aus der Welt jenseits des Portals? Und Ihr kennt Rexxar. Oh ja, auch ich kenne ihn sehr gut.\n\nEr ist mein Sohn.\n\nAber er hat seine Entscheidung vor langer Zeit getroffen. Er ist keiner von uns und hier nicht willkommen. Wir haben genug Probleme mit den Ogern der Totschläger.\n\nIhr müsst eines wissen: ein Halbblut zu sein macht niemanden zu einem Mok'Nathal.", sourceObjective = "Sprecht mit Rexxar in der Donnerfeste im Schergrat.", completion = "Mein Vater ist also tatsächlich am Leben. Ich habe nicht erwartet, dass er mir verzeiht. Das war noch nie seine Art. Aber ich hatte gehofft, dass seine Wut über meine Abreise über die Jahre schwächer geworden ist.\n\nVor dreißig Jahren habe ich die Mok'Nathal verlassen, um der Horde nach Azeroth zu folgen. Leoroxx war strikt dagegen, gab mir aber auch keinen Grund zu bleiben. Und doch hätte ich mir ein herzlicheres Willkommen gewünscht.\n\nEr wollte einen Mok'Nathal als Sohn haben und hat immer noch einen, auch wenn er nichts davon wissen möchte.\n\nIch werde ihm die Augen öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10710] = { id = 10710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Der Singende Bergrücken", description = "Ich habe ein wenig an dem Zephyriumkapazitorium herumgebastelt und bin bereit für einen weiteren Test! Wollt Ihr mir helfen?\n\nDieser nächste Flug sollte kurz, aber schnell sein!\n\nÄh... und obwohl ich mir sicher bin, dass es nicht gefährlich wird... habe ich hier diesen Haftungsausschluss, den Ihr bitte unterschreiben möchtet. Nur eine Formalität, kein Grund zur Sorge!\n\nViel Glück! Sprecht mit Rally, wenn Ihr zum Abschuss bereit seid, und kehrt zu mir zurück, wenn das Experiment vorbei ist!", sourceObjective = "Unterzeichnet Tallys Haftungsausschluss und sprecht mit Rally Zapschnapper, um das Zephyriumkapazitorium zu benutzen.", progress = "Keine Sorge, {name}! Sorgen haben noch niemandem weitergeholfen!", completion = "Wow! Ihr habt schon wieder überlebt! Ich bin ein besserer Ingenieur, als ich immer dachte!\n\nHier ist Eure Bezahlung! Und schaut doch später nochmal bei mir vorbei... Ich habe noch mehr Experimente, für die ich Versuchspersonen brauche!", sourceObjectiveStatus = "unverified-source-field" }
quests[10711] = { id = 10711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Razaans Landeplatz", description = "{name}, ich habe die Effizienz des Zephyriumkapazitoriums um 30 Prozent gesteigert! Ein Versuchsobjekt von Eurem Gewicht wird dann Dank des Luftreibungsverhältnisses in ungeahnte Höhen geschleudert! Wollt Ihr meine Theorie testen? Dieses Experiment sollte Euch in die Nähe von Razaans Landeplatz schicken.\n\nSprecht mit Rally... er wird Euch für den Abschuss vorbereiten.", sourceObjective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium.", completion = "Oh, beeindruckend! So schnell schon zurück! Ich habe gesehen, wie Ihr abgehoben habt und wie eine Rakete in die Luft geschossen seid! Ich dachte, es würde mindestens einen Monat Genesung brauchen, bis Eure gebrochenen Beine wieder geheilt sind! Ihr seid hart im Nehmen, mutig und kühn! Aber vor allem... mutig!", sourceObjectiveStatus = "unverified-source-field" }
quests[10712] = { id = 10712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Ruuanwald", description = "He {name}! Gut, dass ich Euch treffe! Ich habe einen sehr wichtigen Auftrag für Euch.\n\nDas hier ist eine Netherwetterfahne. Ich möchte, dass Ihr während des Flugs ein paar Aufzeichnungen macht und sie zu meinem Vetter im Ruuanwald bringt.\n\nSprecht mit Rally und nehmt einen Flug mit dem Zephyriumkapazitorium zum Ruuanwald. Lasst während dem Flug die Fahne rotieren!\n\nBringt nach Eurer Landung die rotierende Fahne zu O'Mally Zapschnapper.\n\nViel Glück, {name}. Und trödelt nicht!", sourceObjective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Lasst auf Eurem Flug die Netherwetterfahne rotieren. Bringt die rotierende Netherwetterfahne zu O'Mally Zapschnapper im Ewigen Hain.", progress = "Hallo hallo! Mein Klo... äh... mein Vetter Tally hat mir gesagt, dass Ihr vorbeikommen würdet. Habt Ihr etwas für mich?", completion = "Oh, Ihr habt Aufzeichnungen mit der Netherwetterfahne gemacht? Ausgezeichnet! Die Daten dieses Instruments werden zusammen mit meinen Messungen druidischer Magie sicher viele Früchte tragen!\n\nOh, die Einsatzmöglichkeiten werden Euch um den Verstand bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10713] = { id = 10713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und Zeit zu Handeln", description = "Wir werden nicht tatenlos zusehen, wie sie den Ruuanwald um uns herum ausrotten. Unser höchstes Augenmerk muss den Bäumen gelten.\n\n{class}, ich möchte, dass Ihr in den Wald geht und eine ganz besondere Nachricht von uns übermittelt. Ich möchte, dass Ihr jeden einzelnen ihrer Roder, dem Ihr begegnet, tötet.\n\nWenn sie nicht auf vernünftige Argumente hören möchten, dann vielleicht auf schlagkräftige.", sourceObjective = "Tötet 10 Roder des Wyrmkults.", completion = "Danke, {name}.\n\nWir werden uns darum kümmern, dass die Wildtiere sich selbst wieder schnell vermehren. Bei den Bäumen ist dies jedoch ein sehr viel zeitaufwändigerer Prozess.", sourceObjectiveStatus = "unverified-source-field" }
quests[10714] = { id = 10714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf geisterhaften Schwingen", description = "Wenn die Mok'Nathal von den Ogern der Blutschläger tyrannisiert werden, werde ich sie und ihre Anhänger aufhalten. Oger sind einfach gestrickte Wesen. Die Mok'Nathal zu belästigen bringt ihnen keine besonderen Vorteile.\n\nEs muss mehr dahinter stecken, {name}. Nehmt Geisterschwinge, meinen Falken, und belauscht die Gespräche der Anführer der Blutschläger. Er wird unbeobachtet bleiben, wo Ihr auffallen würdet.", sourceObjective = "Sucht einen Zuchtmeister der Blutschläger und einen Sterndeuter der Blutschläger, die sich gerade unterhalten. Benutzt Rexxars Pfeife, um Geisterschwinge zu rufen und sie durch ihn zu belauschen.", progress = "Was habt Ihr erfahren, {name}?", completion = "<Geisterschwinge lässt sich auf Rexxars Schulter nieder, während Rexxar aufmerksam zuhört.>\n\nDie Söhne des Gruul stecken also hinter den Handlungen der Oger. Sie befehlen den Ogern der Blutschlägern, die Mok'Nathal zu vernichten, um ihre Gunst zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10715] = { id = 10715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Grabenschlucht", description = "Euer Rexxar möchte also, dass ich ein Gift für ihn herstelle? Ich werde ihm geben, was er sich wünscht, aber das hat einen Preis, den auch Freunde bezahlen müssen.\n\nZunächst müsst Ihr einen kurzen Weg nach Südwesten in die Grabenschlucht zurücklegen.\n\nDort leben ein paar der giftigsten Kreaturen der ganzen Scherbenwelt, wenn nicht die giftigsten überhaupt. Ich spreche von den Krustenbohrern. Wenn Ihr ein Gift wollt, müsst Ihr ein paar Ihrer Drüsen für mich sammeln.", sourceObjective = "Beschafft Euch 7 Giftdrüsen eines Krustenbohrers.", progress = "Habt Ihr die Giftdrüsen? Wenn nicht, dann hinfort mit Euch und wagt nicht, meine Zeit zu verschwenden, bevor Ihr sie habt!", completion = "Sehr gut, Ihr habt eine einfache, wenn nicht gar banale Aufgabe erfüllt. Nun gebt mir die Drüsen, damit ich den schwierigen Teil erledigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10716] = { id = 10716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Rabenwald", description = "Das Zephyriumkapazitorium ist für seinen bisher längsten Flug bereit! Was meint Ihr, {name}? Wollt Ihr noch einmal fliegen?\n\nIch habe das Antriebssystem verbessert, aber bis ich die passenden Einstellungen gefunden habe, werden wir zusätzlichen Treibstoff brauchen, um ihm den richtigen Kick zu geben! Sprecht vor dem Flug mit Rally, er hat die Einzelheiten.\n\nViel Glück, {name}. Dieser Flug wird Euch zum weit entfernten Rabenwald bringen. Wenn Ihr ihn überlebt - und die Oger und Arakkoa des Waldes - kommt zu mir zurück, damit wir feiern können!", sourceObjective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Kehrt danach zu Tally Zapschnapper in Toshleys Station zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10717] = { id = 10717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilderer wildern", description = "Verzeiht, aber ich konnte nicht umhin, Euer Gespräch mit Chawn mitzuhören. Ich würde gerne helfen.\n\nIch stelle Nachforschungen über den Pechschwingenkoven an und helfe den Druiden, mit ihnen fertigzuwerden.\n\nIch bin sehr daran interessiert, an ein paar ihrer Welplinge zu kommen. Um einen Feind wirklich verstehen zu können, muss man lernen, was er verehrt.\n\nAber zunächst bräuchten wir ein paar Netze. Die Wilderer des Wyrmkults draußen im Ruuanwald haben eine ganze Menge davon.", sourceObjective = "Beschafft Euch 5 Netze des Wyrmkults.", progress = "Wie geht es mit der Beschaffung der Netze voran? Meiner Einschätzung nach sind diese Netze der Wilderer stark genug, um unserer Sache dienlich zu sein.", completion = "Oh, die sehen hervorragend aus. Diese Kultisten wissen wirklich, was wahre Handwerkskunst ist.\n\nZu schade, dass sie sie missbrauchen.\n\nJetzt, da wir die Netze haben, bräuchte ich Eure Hilfe bei ein oder zwei Angelegenheiten. Habt Ihr Lust?", sourceObjectiveStatus = "unverified-source-field" }
quests[10718] = { id = 10718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme der Geister", description = "{name}, jetzt, da Ihr mich sehen könnt, müsst Ihr Rexxar etwas von mir ausrichten. Ich weiß, dass er sein Volk sucht und ich weiß auch, wo es ist.\n\nDie Mok'Nathal haben ein Dorf im Osten, hinter dem Messergrat.\n\nGeht und bringt Rexxar diese Nachricht. Sein Volk ist in Gefahr! Ich weiß, dass er ihnen sehr gerne helfen würde.", sourceObjective = "Sprecht mit Rexxar in der Donnerfeste im Schergrat.", completion = "Wovon redet Ihr?\n\nGarm Wolfsbruder? Er war der letzte Häuptling der Donnerfürsten. Wenn Ihr mit seinem Geist gesprochen habt, muss es wahr sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10719] = { id = 10719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid eingeladen!", description = "Der Kultist hat diese Einladung fallenlassen, die offensichtlich an Aufseher Nuaar übergeben werden sollte. Sie ist mit dem Namen Kolphis Dunkelschuppe unterzeichnet.\n\nBaumhüter Chawn wäre sicher sehr interessiert daran.", sourceObjective = "Bringt die Einladung zum Treffen zu Baumhüter Chawn im Ewigen Hain im Schergrat.", progress = "Was habt Ihr da? Ist da ein Blutfleck auf der Einladung?", completion = "Das ist interessant, aber auch beunruhigend. Vielleicht sollten wir Samia fragen, wer dieser Kolphis Dunkelschuppe ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[10720] = { id = 10720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kleinsten Wesen", description = "So einfältig sie auch sein mögen, würde es den Ogern auffallen, wenn Ihr dieses Gift in ihrem Lager verteilt. Daher will ich Euch beibringen, wie man die Hilfe eines der kleinsten Wesen in der Natur für diese Aufgabe in Anspruch nehmen kann.\n\nWenn Ihr einen einfachen Rhythmus auf dieser Trommel spielt, könnt Ihr ein Murmeltier so beeinflussen, dass es Euren Befehlen gehorcht.\n\nIn der Nähe des Lagers der Blutschläger gibt es einen Murmeltierbau. Er befindet sich im Norden in der Dolchrachenklamm hinter dem Zirkel des Blutes.\n\nBenutzt ein Murmeltier dazu, das Gift in den Fässern der Blutschläger zu verteilen, sobald Ihr es beeinflussen könnt.", sourceObjective = "Begebt Euch zum Murmeltierbau und schlagt die Kodobalgtrommel. Vergiftet die drei Fässer im Lager der Blutschläger, während Ihr das Murmeltier kontrolliert.", progress = "Ist es vollbracht?", completion = "Viele Jahre lang habe ich versucht, die Kommunikation mit der Natur zu perfektionieren. Dies ist nur ein Bruchteil dessen, was die Tiere für Euch tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10721] = { id = 10721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grulloc einen Eber aufbinden", description = "{name}, ich habe einen Eber namens Grummel als Haustier. Er möchte Euch dabei helfen, ein wenig Spaß mit einem der Söhne Gruuls in der Nähe zu treiben.\n\nGrulloc lebt an einem Ort namens Verfluchtes Dunkel. Begebt Euch dorthin und lasst Grummel dann frei. Der Gronn wird es lustig finden, ihn umher zu jagen. Ihr könnt in der Zwischenzeit den Sack, den er bewacht, stehlen und zu Baron Zobelmähne beim Zirkel des Blutes bringen.\n\nIhr gelangt zum Verfluchten Dunkel, indem Ihr den nördlichen Pfad hinunter geht und dann nach Osten durch Drachenend hindurch geht. Das Dunkel befindet sich am östlichen Rand.", sourceObjective = "Beschafft Euch Grullocs Sack.", progress = "So schnell schon zurück? Seid Ihr hier, um Rexxars Schulden zurückzuzahlen?", completion = "<Baron Zobelmähne lugt in den Sack des Gronns und scheint zufrieden.>\n\nSehr gut, Ihr habt Euren Teil der Abmachung gehalten. Nun, da der Preis bezahlt ist, werde ich Rexxar geben, was er begehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10722] = { id = 10722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen am Pechschwingenkoven", description = "Ich weiß, was zu tun ist! {name}, Ihr müsst Euch als Aufseher Nuaar ausgeben und an diesem Treffen teilnehmen!\n\nDie Wyrmkultisten tragen alle ein Standardgewand. Sammelt ein paar Fetzen davon. Wenn Ihr genügend zusammen habt, können wir eine Verkleidung herstellen, in der Ihr an dem Treffen teilnehmen könnt.\n\nSprecht mit Kolphis Dunkelschuppe und hört Euch an, was er zu sagen hat. Kehrt danach zu mir zurück.\n\nIhr findet den Koven indem Ihr durch den Tunnel des Wyrmschädels geht und dem Pfad durch den Rabenwald Richtung Grishnath bis zum Ende folgt.", sourceObjective = "Sammelt genügend Gewandfetzen von verschiedenen Wyrmkultisten, um eine Aufseherverkleidung herzustellen. Benutzt die Verkleidung, um am Treffen mit Kolphis Dunkelschuppe teilzunehmen.", completion = "Uns angreifen? Uns auslöschen? Das glaube ich aber nicht!\n\nDieser Pechschwingenkoven muss noch viel lernen, wenn sie denken, dass man die Expedition des Cenarius so leicht loswerden kann!\n\nWie sagt man so schön? Wie du mir, so ich dir!", sourceObjectiveStatus = "unverified-source-field" }
quests[10723] = { id = 10723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom der Drachenfresser", description = "Der Gronn, den wir suchen, heißt Gorgrom der Drachenfresser. Mit Zobelmähnes Falle werdet Ihr ihm kurzen Prozess machen können. Ihr könnt ihn wahrscheinlich antreffen, wenn er die Opfer der Oger von Fels'mok entgegen nimmt.\n\nFolgt der Straße, die nach Norden vom Zirkel des Blutes weg führt, und wendet Euch dann beim Ruuanwald nach Westen. Durchquert danach den Tunnel nach Nordwesten.\n\nTötet zunächst die Oger, um an ihre Köpfe zu kommen. Stellt danach die Falle bei Gorgroms Altar auf und wartet auf seine Ankunft. Tötet ihn und stellt dann die Köpfe als grausige Totems um seine Leiche herum auf. Diese Nachricht sollte man nicht missverstehen können.\n\nNehmt den Bären mit!\n\n<Misha knurrt.>", sourceObjective = "Sammelt 3 grausige Totems von den Ogern von Fels'mok. Stellt danach Zobelmähnes Falle bei Gorgroms Altar auf, um Gorgrom den Drachenfresser zu rufen, und tötet ihn.\n\nWenn Gorgrom tot ist, platziert die drei grausigen Totems in der Nähe seiner Leiche.", progress = "Die Oger der Blutschläger werden uns nie mehr belästigen, wenn Ihr Eure Aufgabe erfüllt habt.", completion = "Die Oger der Blutschläger und ihr Meister, Gorgrom, werden die Mok'Nathal nie wieder belästigen.\n\nIch mache mir jedoch Sorgen über die Auswirkungen unserer Tat auf die anderen Gronn. Ich glaube, wir müssen diesem Kampf ein für alle Mal ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10724] = { id = 10724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangener der Speerspießer", description = "Kurz nach meiner Ankunft in den Bergen wurde ich von einer Gruppe von Ogern der Speerspießer angegriffen.\n\nIch konnte mich zwar freikämpfen, doch sie haben es geschafft, meinen Wyvern Leokk zu entführen. Geisterschwinge hat ihn gefunden. Er wird in der Mitte des Lagers der Speerspießer außerhalb von Gruuls Unterschlupf in einem Käfig gefangen gehalten.\n\nEiner der Oger muss den Schlüssel dazu haben. Findet ihn, dann kann Geisterschwinge damit Leokks Käfig öffnen.\n\nDas Lager liegt dort unten am nördlichen Ende der Dolchrachenklamm.", sourceObjective = "Tötet die Oger der Speerspießer, um an den Wyvernkäfigschlüssel zu kommen. Sobald Ihr ihn habt, benutzt Geisterschwinges Pfeife, um Geisterschwinge zu rufen, der den Käfig öffnen wird, um Leokk zu befreien.", completion = "Leokk hat uns den Kopf eines schwarzen Drachen von Drachenend gebracht, damit können wir Goc, den Gronn, der ihn gefangen genommen hat, erzürnen und ihn in die Schlacht locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10725] = { id = 10725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geachtet vom Violetten Auge", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, {name}. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10726] = { id = 10726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geachtet vom Violetten Auge", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, {name}. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10727] = { id = 10727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geachtet vom Violetten Auge", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, {name}. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10728] = { id = 10728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geachtet vom Violetten Auge", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, {name}. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10729] = { id = 10729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Magiers", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10730] = { id = 10730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Bewahrers" }
quests[10731] = { id = 10731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Auftragsmörders", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10732] = { id = 10732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Beschützers" }
quests[10733] = { id = 10733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10734] = { id = 10734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10735] = { id = 10735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10736] = { id = 10736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10737] = { id = 10737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung des Meisters", description = "Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.\n\nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.\n\nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.", sourceObjective = "Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10738] = { id = 10738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, {name}. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", sourceObjectiveStatus = "unverified-source-field" }
quests[10739] = { id = 10739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10740] = { id = 10740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10741] = { id = 10741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10742] = { id = 10742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale", description = "Jetzt geht es wie folgt weiter. Wir locken Goc von seinem Unterschlupf weg und vernichten ihn. Wenn Goc tot ist, werden die Oger der Speerspießer die Mok'Nathal nie mehr belästigen. Geht zu Gocs Altar außerhalb von Gruuls Unterschlupf und blast dann in mein Horn. Ich werde kommen und zusammen werden wir Gruuls Sohn zur Strecke bringen.", sourceObjective = "Benutzt Rexxars Kampfhorn beim Altar von Goc und tötet Goc.", progress = "Nur wenn Goc und Gorgrom der Drachenfresser tot sind, werden die Mok'Nathal frei sein.", completion = "Der Kampf war hart und Ihr habt Euch gut geschlagen, {name}. Ich bin stolz, dass ich in der Schlacht gegen Goc an Eurer Seite kämpfen durfte.\n\nDie Mok'Nathal sollten von diesen großartigen Siegen erfahren, aber ich bin noch nicht bereit, ihnen gegenüberzutreten. Ich kenne meinen Vater und ich kenne mein Herz. Es gibt immer noch vieles, was ich lernen und tun kann, um stärker zu werden und ihm zu beweisen, dass ich sein wahrer Sohn bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[10743] = { id = 10743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Mok'Nathal" }
quests[10744] = { id = 10744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Sieg", description = "Ihr müsst sofort Kurdran Wildhammer von unserem Sieg berichten! Seine Leute haben unter Schwadronskommandant Nuainn rund um die Uhr gekämpft, um die Wildhammerfeste zu schützen. Eure Rückkehr wird sie sicher anspornen. Jetzt, da die Bedrohung der Legion aus dem Weg geräumt ist, kann Kurdran sich endlich Illidans Streitkräften widmen. Unsere Stellung hier ist noch lange nicht gesichert, aber wir haben heute einen entscheidenden Sieg errungen.", sourceObjective = "Kehrt zur Wildhammerfeste zurück und sprecht mit Kurdran Wildhammer.", completion = "<Kurdran hört Euren Bericht an.>\n\nDas sind in der Tat gute Nachrichten! Noch vor ein paar Tagen hätte ich mir nie träumen lassen, dass wir der Belagerung der Legion ein Ende machen könnten.\n\nIhr habt nicht nur ihren Angriff verhindert, sondern auch noch ihre Maschinerie vernichtet! Für diesen Heldenmut habt Ihr den Dank der Wildhämmer, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10745] = { id = 10745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Sieg", description = "Ihr müsst sofort Oberanführer Or'barokh von unserem Sieg berichten! Jetzt, da wir die Legion geschlagen und ihre Anwesenheit im Schattenmondtal beendet haben, kann der Oberanführer sich endlich unseren anderen Feinden widmen.\n\nAuch wenn die Wache der Kor'kron es nie zugeben würden, werden sie erleichtert sein, nicht mehr an zwei Fronten gleichzeitig kämpfen zu müssen.", sourceObjective = "Kehrt nach Schattenmond zurück und sprecht mit Oberanführer Or'barokh.", completion = "<Der Oberanführer hört Euren Bericht an.>\n\nAusgezeichnete Nachrichten! Den Angriffen der Legion standzuhalten nahm einfach viel zu viele Leute in Anspruch. Ich habe zwar nie geglaubt, dass meine Leute versagen würden, aber sie standen unter großer Belastung.\n\nIhr habt heute bewiesen, wie wichtig Ihr für die Horde seid. Die Wache der Kor'kron wird sich jederzeit geehrt fühlen, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10746] = { id = 10746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Weisen", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10747] = { id = 10747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welpen des Wyrmkults", description = "Wie ich bereits sagte würde es uns helfen, den Kult zu verstehen, wenn wir einige der Welpen, die sie beim Pechschwingenkoven züchten, untersuchen.\n\nSo wie ich das verstanden habe, müssen in ihrem höhlenartigen Lager eine ganze Menge von Welpen herumfliegen. Dort sind auch ein paar Eier, die wahrscheinlich schlüpfen werden, wenn Ihr ihnen zu nahe kommt.\n\nBitte, {name}, nehmt das Netz und sammelt ein paar davon lebend für mich.\n\nIhr findet den Koven im Westen. Überquert die Brücke des Wyrmschädels und nehmt dann den Tunnel des Wyrmschädels. Folgt dem Pfad durch den Rabenwald Richtung Grishnath bis zum Ende.", sourceObjective = "Verwendet das Schwarzwelpennetz, um 10 Schwarzwelpen des Wyrmkults zu fangen.", progress = "Hattet Ihr viel Ärger beim Versuch, die Welpen zu fangen? Ich hoffe, Ihr habt Euch nicht verbrannt!", completion = "Ach herrje, das sind ja mehr, als ich gehofft hatte! Für Euren Heldenmut habt Ihr gewiss ein Lob verdient!\n\nDiese Welpenbrut sieht sehr gut aus. Sie sind wie gemacht für meine Untersuchungen.\n\nBitte, nehmt eine kleine Belohnung von mir an. Ich bestehe darauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[10748] = { id = 10748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maxnar muss sterben!", description = "Sie haben uns keine andere Wahl gelassen, {name}. Es ist an der Zeit, der Bedrohung am Pechschwingenkoven ein Ende zu setzen. Wir müssen ihren Anführer, Maxnar den Aschenmagen, erschlagen.\n\nIch weiß nicht, ob Ihr ihn schon zu Gesicht bekommen habt, als Ihr dort wart, aber er ist ein Drachkin, halb Mensch, halb Drache. Und er ist ganz schön zäh, also unterschätzt ihn nicht!\n\nErledigt ihn schnell. Mit etwas Glück bringt Ihr so die Sicherheit in den Ewigen Hain und den Ruuanwald zurück.", sourceObjective = "Tötet Maxnar den Aschenmagen.", completion = "Jetzt, da der Anführer unserer Feinde tot ist, können wir endlich wieder ein wenig aufatmen. Und Ihr habt auch noch das gesamte Gebirge vor ihrer Verwüstung bewahrt.\n\nWas auch immer ihre endgültigen Pläne gewesen sein mögen, Ihr habt sie vereitelt!\n\nIhr habt unseren Dank, {name}. Bitte nehmt dieses Zeichen unserer Wertschätzung sowie unsere ewig währende Gastfreundschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[10749] = { id = 10749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähnes Gift", description = "Hier, bringt dies zu Eurem Auftraggeber. Ich bin mir sicher, dass Rexxar es sinnvoll einzusetzen weiß.\n\nOh, und stellt sicher, dass er sich im Klaren ist, dass er mir etwas schuldet.\n\nEr weiß, was ich will. Ich bin mir sicher, dass wir uns - ganz gleich, wie er es zu beschafften gedenkt - schneller wiedersehen werden, als Ihr vielleicht denkt.\n\nJetzt seid ein <braver Junge/braves Mädel> und bringt dies zu Rexxar.", sourceObjective = "Bringt Baron Zobelmähnes Gift zu Rexxar in der Donnerfeste im Schergrat.", progress = "{class}, so schnell schon zurück? Habt Ihr das Gift?", completion = "Die Verwendung von Giften ist ein dreckiges Geschäft. Aber so werden wir unsere Ziele erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10750] = { id = 10750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Eroberung", description = "Meine Windreiter sind mit ein paar Neuigkeiten zurückgekehrt, {name}. Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt weit im Südosten und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Windreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", sourceObjective = "Reist zum Pfad der Eroberung im Schattenmondtal.", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10751] = { id = 10751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad bereinigen", description = "Wir brauchen mehr Zeit, {race}! Ich werde mit den anderen Windreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Windreiter mithilfe der Leuchtpistole der Kor'kron!", sourceObjective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 10 Zauberbinder der Mondfinsternis.", completion = "Ihr werdet es nicht glauben, Grunzer!", sourceObjectiveStatus = "unverified-source-field" }
quests[10752] = { id = 10752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Eschental!", description = "Vor Kurzem kam Raene Wolfsläufer aus Darnassus durch Auberdine. Sie war auf dem Weg ins Eschental und murmelte etwas von Furbolgs. Ich hatte keine Gelegenheit, sie genauer dazu zu befragen, aber vielleicht könnt Ihr Euch ja auf die Suche nach ihr begeben und ihr Eure Hilfe anbieten, {class}. Nehmt die südliche Straße aus Auberdine hinaus. Folgt der Straße einfach weiter, sobald Ihr die Grenze zum Eschental erreicht habt. Dort findet Ihr schließlich Astranaar und Raene Wolfsläufer.", sourceObjective = "Sprecht mit Raene Wolfsläufer in Astranaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10753] = { id = 10753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis ausmerzen", description = "Die Zahl der Verbrechen, die die Brennende Legion begangen hat, steigt ins Unermessliche. Genau in diesem Moment schickt die Legion wieder ihre Truppen aus, um die Lebewesen dieser Welt heimzusuchen. Sie sind ihrer Macht hilflos ausgeliefert und fallen einer nach dem anderen ihrer Gewalt zum Opfer. {name}, helft mir dabei, diese Verbrechen gegen die Natur aufzuhalten, und vernichtet alles, was von ihrer Verderbnis befallen wurde.\n\nHinter den Bergen im Osten könnt Ihr sehen, wie sich die Verderbnis in der Messerschlucht ausbreitet. Tötet die Verantwortlichen, die Teufelsverderber und so viele Teufelsanbeter, wie Ihr nur könnt.", sourceObjective = "Tötet 4 Wesen der Schuppenflügelteufelsbrut, 4 Wesen der Dolchrachenteufelsbrut und 2 Teufelsverderber.", completion = "Es erfüllt mich nicht mit Stolz zu zerstören, was Elune erschaffen hat, aber die Verderbnis muss aufgehalten werden. Ihr habt Eure Arbeit gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10754] = { id = 10754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang zur Zitadelle", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Danath, der Truppenkommandant der Ehrenfeste, dafür.", sourceObjective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Danath in der Ehrenfeste auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10755] = { id = 10755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang zur Zitadelle", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Nazgrel, der Anführer der Streifkräfte der Horde in Thrallmar, dafür.", sourceObjective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10756] = { id = 10756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Rohok", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Rohok, unserem Schmied hier. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", sourceObjective = "Bringt die präparierte Schlüsselform zu Rohok nach Thrallmar auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10757] = { id = 10757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohoks Bitte", description = "Die Schmiedekunst der Höllenorcs mag nicht gerade die anspruchsvollste sein, aber es ist dennoch Geschick für ihr Handwerk von Nöten. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", sourceObjective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Rohok in Thrallmar auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10758] = { id = 10758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer als die Hölle", description = "Es klappt nicht, {name}! Egal wie viele Kohlen ich auf das Feuer lege, die Hitze des Feuers reicht einfach nicht aus.\n\nMir fällt nur noch eine Sache ein, die heiß genug sein könnte, um diesen Schlüssel auf die richtige Temperatur zu bringen, und das ist das Innere eines Teufelshäschers der Legion.\n\nIch habe bisher nur einmal gesehen, wie einer niedergestreckt wurde. Seine Innereien rauchten, brannten und dampften, als er fiel. Nehmt diese Form und haltet sie in einen gefallenen Teufelshäscher. Ich würde Euch empfehlen, ein paar Freunde mitzunehmen, falls Ihr vorhattet, ihn alleine zur Strecke zu bringen.", sourceObjective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Rohok in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10759] = { id = 10759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Deserteur", description = "Ich habe das Gefühl, dass alle Teile des Puzzles vor meinen Augen liegen, aber ich kann sie einfach nicht sinnvoll zusammensetzen.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Nordwesten. Wahrscheinlich hat er dort Zuflucht gesucht.", sourceObjective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", completion = "<Der Arakkoa kichert.>\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10760] = { id = 10760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wrack der Sketh'lon", description = "Das Wrack der Sketh'lon, direkt im Osten, ist ein unheimlicher Ort. Die Peons sind davon überzeugt, dass es dort spukt.\n\nEs gibt dort ein paar Bäume, deshalb haben die Peons keine andere Wahl, als in die Ruinen der Arakkoa zu gehen und Holz zu schlagen. Die Geister der Arakkoa nähren sich an den Arbeitern. Sie saugen ihre Lebensenergie auf und benutzen sie, um ihre verdorbene Magie zu verstärken.\n\nWir müssen herausfinden, was den Dunklen Rat dazu treibt und ihn aufhalten, bevor sein Einfluss überhand nimmt. Durchsucht das Wrack der Sketh'lon nach Hinweisen auf ihre Pläne.", sourceObjective = "Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Unteroffizier Kargrul in Schattenmond.", progress = "Was habt Ihr herausgefunden?", completion = "<Der Unteroffizier untersucht die Tagebuchseiten.>\n\nHier steht nicht viel Sinnvolles, aber ein paar Einträge könnten sich als nützlich erweisen. Wie es aussieht waren die Arakkoa dabei, ein kompliziertes magisches Ritual vorzubereiten, bis sie starben, aber warum? Hier steht auch etwas Merkwürdiges über einen 'Deserteur'.", sourceObjectiveStatus = "unverified-source-field" }
quests[10761] = { id = 10761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Deserteur", description = "Hier steht nichts, was erklären würde, warum die Geister dieser Arakkoa in dieser Welt zurückbleiben oder wie sie ihren Durst nach Orcblut entwickelt haben.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Südosten. Wahrscheinlich hat er dort Zuflucht gesucht.", sourceObjective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", completion = "<Der Arakkoa kichert.>\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10762] = { id = 10762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Dumphry", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Dumphry. Er ist ein Meister seiner Kunst. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", sourceObjective = "Bringt die präparierte Schlüsselform zu Dumphry in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10763] = { id = 10763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dumphrys Bitte", description = "Die Höllenorcs mögen vollkommene Barbaren sein, aber ihre Schmiedekunst ist nicht so primitiv, wie Ihr denken mögt. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", sourceObjective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Dumphry in der Ehrenfeste auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10764] = { id = 10764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer als die Hölle", description = "Es funktioniert nicht, <Kumpel/Mädel>. Ich kann einfach nicht genug Hitze erzeugen... die Materialien kommen nicht auf ausreichende Temperaturen.\n\nDie Teufelshäscher der Brennenden Legion werden von einem sengenden Kern aus Teufelsfeuer angetrieben, der viel heißer als gewöhnliches Feuer ist.\n\nWenn Ihr genügend Leute zusammentrommeln könntet, um einen davon zur Strecke zu bringen, könntet Ihr die Schlüsselform in dem gefallenen Häscher aufheizen. Aber seid vorsichtig, {class}, diese Teufelshäscher können ganz schön zuschlagen!", sourceObjective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Dumphry in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10765] = { id = 10765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Welten kollidieren...", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfenkanzlerin aussah. Vielleicht habt Ihr auch schon die kleineren Riesen auf dem Pfad bemerkt. Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", sourceObjective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10766] = { id = 10766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Katastrophe", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Die Wildhammerfeste ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Plexi erwartet Euch bereits am Ankunftsort.", sourceObjective = "Meldet Euch bei Plexi im Invasionspunkt: Katastrophe.", completion = "Es freut mich, Euch kennen zu lernen, {name}. Mein Name ist Plexi.\n\nIch werde Euch nicht mit Höflichkeiten langweilen. Wir wissen beide, warum wir hier sind. Und nun an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10767] = { id = 10767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Katastrophe", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Schattenmond ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Nakansi erwartet Euch bereits am Ankunftsort.", sourceObjective = "Meldet Euch bei Nakansi im Invasionspunkt: Katastrophe.", completion = "Ihr müsst derjenige sein, von dem Blutwache Gulmok gesprochen hat. Ich habe bereits einen Plan, aber ich brauche Eure Hilfe, um die Vorbereitungen abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10768] = { id = 10768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenröcke der Illidari", description = "Die Windreiter müssen nach Schattenmond zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Kor'kron, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, {race}?", sourceObjective = "Sammelt 10 Wappenröcke der Illidari.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10769] = { id = 10769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwietracht in den Rängen...", description = "Forscher Tiorus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", sourceObjective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Oberanführer Or'barokh in Schattenmond im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Kor'kron zurück.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Grunzer ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n<Or'barokh nickt.>\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[10770] = { id = 10770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Funken", description = "Nordöstlich von hier, auf der Ebene über uns, liegt mein altes, zu Asche verbranntes Zuhause. Bevor die Legion ihre Sengwichtel geschickt hat, um uns in Flammen aufgehen zu lassen, stand dort einst ein stattlicher Wald. Dabei sind so viele ums Leben gekommen, dass sich mein altes Herz auch noch Jahrhunderte später nach Rache sehnt. Es sind zu viele von ihnen dort, um das Land tatsächlich zurückzufordern, aber Ihr könntet ihnen vielleicht ein wenig Angst einjagen.\n\nIhr werdet mir doch helfen, oder?", sourceObjective = "Moosborke der Uralte möchte, dass Ihr 8 Sengwichtel tötet und danach zu ihm im Ruuanwald zurückkehrt.", completion = "Es gibt so viele, dass wir sie nie alle töten können, aber Ihr habt mir Hoffnung gegeben. Vielleicht sollte ich noch ein paar Jahrhunderte lang stärker versuchen, meinen geliebten Wald wieder zum Leben zu erwecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10771] = { id = 10771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Asche", description = "Wenn Ihr der Straße nach Osten den Berg hinauf folgt und dann nach Norden abbiegt, gelangt Ihr an mein altes Zuhause.\n\nEinst stand dort ein prächtiger Wald, dessen Name schon lange vergessen ist. Doch vor ewigen Zeiten rief die Brennende Legion Sengwichtel und andere Flammenwesen herbei, zerstörte mein Zuhause und zwang mein Volk zu fliehen. Nun bin nur noch ich übrig.\n\nIch habe ein paar Eisenwurzelsamen aufgehoben, die in fruchtbaren vulkanischen Boden gepflanzt werden können. Ihre Magie ist sehr stark. Bitte tut mir diesen Gefallen und ich werde die Schätze längst vergangener Zeiten mit Euch teilen.", sourceObjective = "Moosborke der Uralte möchte, dass Ihr nach Skald reist und Eisenwurzelsamen in drei verschiedene Hügel fruchtbarer Vulkanerde pflanzt. Kehrt danach zu ihm im Ruuanwald zurück.", progress = "Ist es vollbracht? Habt Ihr etwas Leben in mein altes Zuhause zurückgebracht?", completion = "Ihr habt viele dieser verderbten Kreaturen getötet. Mit dieser Gewissheit kann ich nun etwas ruhiger schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10772] = { id = 10772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Eroberung", description = "Meine Greifenreiter sind mit ein paar Neuigkeiten zurückgekehrt! Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt östlich von hier und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Greifenreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", sourceObjective = "Reist zum Pfad der Eroberung im Schattenmondtal.", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10773] = { id = 10773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad bereinigen", description = "Wir brauchen mehr Zeit, {race}! Ich werde mit den anderen Greifenreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Greifenreiter mithilfe der Leuchtpistole der Wildhämmer!", sourceObjective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 5 Söhne des Corok.", completion = "Ihr werdet es nicht glauben, Soldat!", sourceObjectiveStatus = "unverified-source-field" }
quests[10774] = { id = 10774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelf + Riese = ???", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfe aussah. Was machen die Riesen überhaupt hier? Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", sourceObjective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10775] = { id = 10775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenröcke der Illidari", description = "Die Greifenreiter müssen zur Wildhammerfeste zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Wildhämmer, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, {race}?", sourceObjective = "Sammelt 10 Wappenröcke der Illidari.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10776] = { id = 10776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwietracht in den Rängen...", description = "Gnomus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", sourceObjective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Than Yoregar in der Wildhammerfeste im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Wildhämmer zurück.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Soldat ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n<Yoregar nickt.>\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[10777] = { id = 10777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asghars Totem", description = "Was im Tagebuch des Kommandanten steht, ist wahr. Während sich die orcische Horde unter Gul'dan sammelte, versuchte mein Volk, diese Bedrohung abzuwenden, indem sie einen Angriff planten. Gul'dan erfuhr jedoch davon und wirkte einen mächtigen Zauber, der unsere Lager zerstörte und die Geister meiner Brüder zerbrach.\n\nSie müssen aufgehalten werden, bevor sie noch mehr Unheil anrichten. Sucht nach Asghar beim Wrack der Sketh'lon im Norden und bringt mir das Totem, das er bei sich trägt. Damit können wir beginnen, die Pläne des Dunklen Rats zu vereiteln.", sourceObjective = "Bringt das Kriegstotem der Sketh'lon zu Parshah in den Magmafeldern.", progress = "Habt Ihr das Totem von Asghar beschafft?", completion = "<Parshah untersucht das Totem.>\n\nGut. Dieses alte Totem hat seine Macht über die Jahre nicht eingebüßt, doch es alleine reicht noch nicht aus, um den Dunklen Rat aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10778] = { id = 10778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rute von Lianthe", description = "Das Totem alleine ist nicht stark genug, um der teuflischen Magie des Dunklen Rats entgegen zu wirken.\n\nWir können es jedoch mit anderen mächtigen Gegenständen zu einem Stab verarbeiten, mit dem wir die Energien bündeln können. Es ist nicht mehr möglich, meine Brüder aus den Tiefen ihrer Verderbtheit zu erretten, aber wir können sie aufhalten.\n\nEiner dieser Gegenstände, den ich benötige, ist die Rute von Lianthe, die sich im Besitz der Blutelfen in der Stätte der Mondfinsternis im Südosten befindet. Sie wird in einem Pavillon ganz oben in den Ruinen aufbewahrt und sehr schwer bewacht. Seid vorsichtig, {name}.", sourceObjective = "Besorgt Euch den Schlüssel von Lianthe von den Blutelfen in der Stätte der Mondfinsternis und benutzt ihn, um die Geldkassette von Lianthe zu öffnen und die Rute von Lianthe an Euch zu nehmen. Bringt die Rute zu Parshah in den Magmafeldern.", progress = "Konntet Ihr die Rute beschaffen?", completion = "Gut gemacht. Ein solcher Schatz verdient besseres, als in einer dunklen Kiste weggesperrt zu werden. Wir werden ihn für einen guten Zweck einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10779] = { id = 10779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht aus, als wärt Ihr bereits tüchtig genug, um ein Tier auszubilden und zu Eurem Begleiter zu machen.\n\nSprecht mit Kella Nachtbogen auf der Azurmythosinsel. Sie kann Euch beibringen, wie man ein eigenes Tier beherrscht.", sourceObjective = "Sprecht mit Kella Nachtbogen auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10780] = { id = 10780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn der Sketh'lon", description = "Uns fehlt noch ein letztes Element des Stabs. Wir müssen seine Macht gegen die Geister des Dunklen Rats richten.\n\nDies erreichen wir, indem wir Federn bei den Ruinen des Basislagers der Sketh'lon sammeln und an dem Stab befestigen. Das Basislager befindet sich im Süden, östlich der Wildhammerfeste.\n\nGul'dans Magie hat meine Brüder vernichtet und nur ihre Geister übrig gelassen, doch das war nicht alles. Die Magie hat sich an dem Zauber, den die Arakkoa vorbereiteten, genährt und eine ruchlose Macht erschaffen, die die Geister in ihren Bann gezogen hat.", sourceObjective = "Sammelt 8 Federn der Sketh'lon und bringt sie zu Parshah in den Magmafeldern.", progress = "Habt Ihr die Federn für den Stab schon gesammelt?", completion = "<Parshah nimmt Euch die aschebestäubten Federn ab und schüttelt den Kopf.>\n\nEs wäre besser gewesen, wenn ich an diesem Tag gestorben wäre, aber die Dinge sind niemals so einfach. Dass Gul'dans Magie sie in etwas verwandelt hat, das sie aufzuhalten versuchten, ist ein grausames Spiel des Schicksals.", sourceObjectiveStatus = "unverified-source-field" }
quests[10781] = { id = 10781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht an der Purpurwacht", description = "Während wir uns hier unterhalten, suchen sie Euch wahrscheinlich auf dem Pfad der Eroberung. Ihr müsst fliehen, {race}!\n\nLasst mich zurück, ich bin ohnehin dem Untergang geweiht... Sie... Ich glaube, ich höre sie kommen. Jetzt oder nie! Flieht! Wenn Ihr bleibt, werdet Ihr kämpfen müssen!\n\nWenn Ihr doch kämpft und es irgendwie schafft, zu überleben, berichtet A'dal in Shattrath von dem, was Ihr gesehen habt!", sourceObjective = "Bekämpft Illidans Truppen bei der Purpurwacht und überlebt!\n\nKehrt zu A'dal in Shattrath zurück, wenn Ihr als Sieger aus der Schlacht hervorgehen solltet.", completion = "Wir werden weitere Nachforschungen über das Purpursiegel anstellen. Sie stellen eine Bedrohung für alles Leben in Draenor dar. Ich sehe einen Tag voraus, an dem ihr dunkler Herr für seine Verbrechen geradestehen muss. Vielleicht seid Ihr ja diejenige, der ihn der Gerechtigkeit zuführen wird, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10782] = { id = 10782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kopfstück mit Magie erfüllen", description = "Der Stab ist fast fertig!\n\nJetzt müssen wir nur nach das Kopfstück mit der Macht von Gul'dans Echo, das durch diesen verfluchten Ort hallt, erfüllen. Im Osten, in der Nähe der Teufelsgruben und südlich der Todesschmiede, befindet sich der Altar der Verdammnis.\n\nDort sind Teile der Vergangenheit gefangen. Wenn Ihr das unfertige Kopfstück des Stabs in die Gegend um den Altar herum bringt, werden einige Wesenheiten darauf reagieren. Seid also auf der Hut. Ihr tragt einen sehr gefährlichen Gegenstand bei Euch, der eng mit der Katastrophe zusammenhängt.", sourceObjective = "Reist zum Altar der Verdammnis und benutzt das unfertige Kopfstück, während Ihr in der Nähe von Gul'dan steht. Kehrt zu Parshah in den Magmafeldern zurück, wenn Ihr das Kopfstück aufgeladen habt.", progress = "Seid Ihr mit dem magieerfüllten Kopfstück zurück?", completion = "<Parshah nimmt Euch das Kopfstück ab und hält es behutsam in den Händen.>\n\nDieses Kopfstück enthält die Macht, die wir brauchen, um die Pläne des Dunklen Rats im Basislager der Sketh'lon zunichtezumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10783] = { id = 10783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähne", description = "Das ist mein Plan. Wir werden die Oger vergiften und dann ihren Gronnmeister vernichten.\n\nWährend meinen Reisen in diesen Bergen habe ich einen Mann namens Baron Zobelmähne getroffen. Er ist ein Meister der Alchemie und lässt sich vielleicht davon überzeugen, uns zu helfen.\n\nIhr findet ihn beim Zirkel des Blutes, unten in der Schlucht nördlich von hier. Welchen Preis er auch immer verlangen mag, nehmt ihn an!", sourceObjective = "Sprecht mit Baron Zobelmähne beim Zirkel des Blutes im Schergrat.", completion = "Hallo, {race}. Ich bin Baron Zobelmähne. Ein Freund Rexxars ist auch mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10784] = { id = 10784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet das Lager der Blutschläger!", description = "<Tor'chunk beugt sich zu Euch herüber und flüstert.>\n\n{name}, mit Euren Erfolgen im Kampf gegen die Oger bisher habt Ihr uns mehr als stolz gemacht. Und auch wenn ich vollstes Vertrauen in Rexxars Plan habe, möchte ich Euch trotzdem bitten, die Oger im Lager der Blutschläger zu vernichten, bevor Ihr zurückkehrt.\n\nSo können wir unseres Erfolgs doppelt sicher sein.\n\nIhr gelangt in das Lager, indem Ihr den Weg nach Norden aus der Donnerfeste hinausgeht. Wendet Euch am Ende des Steilwegs nach Westen durch Drachenend hindurch und dann nach Norden durch die Grabenschlucht und die Dolchrachenklamm.", sourceObjective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", completion = "<Tor'chunk nickt und scheint dabei sichtlich zufrieden mit Eurer mörderischen Kühnheit.>\n\nIhr erstaunt mich immer wieder, {name}. Jedes Mal, wenn einer dieser stinkenden Oger zu Boden geht, sind wir einen Schritt näher daran, einen unwürdigen Feind loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10785] = { id = 10785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist eine Falle!", description = "Es gibt nichts, was ich auf der Welt mehr hasse als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nBeeilt Euch und bringt die Falle zu Rexxar. Mein Rachedurst muss gestillt werden!", sourceObjective = "Bringt die Drachenfeuerfalle zu Rexxar in der Donnerfeste im Schergrat.", progress = "Habt Ihr bekommen, was auch immer in diesem Sack des Gronns war? Habt Ihr es Zobelmähne gebracht? Hat er Euch etwas für mich mitgegeben?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10786] = { id = 10786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemetzel in Fels'mok", description = "Ich weiß, dass Rexxar Euch nach Fels'mok schicken möchte. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichtemachen!\n\nFels'mok liegt weit im Nordwesten. Reist nach Norden zum Ruuanwald und von dort aus nach Westen durch den Tunnel hinter den Rabenwald.\n\n{name}, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok tötet. Radiert sie aus!", sourceObjective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok. Kehrt danach zu Tor'chunk Zweiklaue in der Donnerfeste im Schergrat zurück.", completion = "<Tor'chunk grinst, als Ihr ihm von Euren Abenteuern in Fels'mok erzählt.>\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, {name}, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10787] = { id = 10787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachen von Drachenend", description = "Wir müssen etwas tun, dass Goc erzürnt, wenn wir ihn uns vorknöpfen wollen.\n\nUnd nun, da Ihr Leokk befreit habt, weiß ich auch ganz genau, was das sein wird.\n\nWenn Ihr bereit seid, werde ich Leokk bitten, Euch zu einem der Drachenkadaver auf den Felsen von Drachenend zu fliegen.\n\nNehmt den Kadaver und bringt ihn zu mir, damit wir daraus etwas herstellen können, was Goc aus seinem Versteck locken wird.", sourceObjective = "Rexxar bittet Euch, auf Leokk nach Drachenend zu fliegen und einen Kadaver eines schwarzen Drachend zu besorgen. Kehrt danach zu ihm in der Donnerfeste im Schergrat zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10788] = { id = 10788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Talionia zurück", description = "Einer Eurer Meister, Talionia in Silbermond, schickt nach Euch, {name}. Ich bin mir sicher, dass für Euch die Zeit gekommen ist zu lernen, wie man einen mächtigeren Dämon beschwört und kontrolliert. Ich schlage daher vor, dass Ihr Euch sofort auf den Weg macht. Wie ich weiß befindet sich Talionia im Sanktum, einer gemütlichen kleinen Hütte des Bösen an der Mördergasse.", sourceObjective = "Sprecht mit Talionia in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[10789] = { id = 10789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Carendin Halgar", description = "Ah, da seid Ihr ja, {name}.\n\nCarendin Halgar schickt nach Euch. Ihr sollt ihn im Magieviertel von Unterstadt aufsuchen. Er ist nicht gerade für seine Geduld bekannt, daher würde ich ihn an Eurer Stelle nicht so lange warten lassen.", sourceObjective = "Sprecht mit Carendin Halgar in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10790] = { id = 10790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Gan'rul Blutauge", description = "Ihr seid weit von zu Hause entfernt, {race}. Vielleicht ist es an der Zeit, dass Ihr zurückkehrt, um von Eurem Meister Gan'rul Blutauge zu lernen. Für sein Wissen ist er bei allen, die etwas von der Kunst verstehen, bekannt, sogar bei uns hier.\n\nGan'rul lebt in der Kluft der Schatten in Orgrimmar.", sourceObjective = "Sprecht mit Gan'rul Blutauge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10791] = { id = 10791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen Wolfgeist!", description = "Ich habe die Gewandung, die ich während der Zeremonie tragen werde, fast fertig. Während ich die letzten Handgriffe erledige, möchte ich Euch bitten, diesen Weihrauch bei den Kerzen in der Nähe des Runensteins zu meiner Linken zu platzieren.\n\nIch glaube, dass er uns dabei helfen wird, die Aufmerksamkeit des Wolfgeistes zu erlangen, da er aus den Tagen der orcischen Klans stammt. Ich kann fast schon sehen, wie meine Vorfahren ihn in einer Zeremonie entzündeten, in der sie dem Wolfgeist nach einer erfolgreichen Jagd dankten.\n\nSobald Ihr den Weihrauch platziert habt, werde ich mit der Zeremonie beginnen.", sourceObjective = "Benutzt den zeremoniellen Weihrauch in der Nähe der Kerzen in Malukaz' Hütte und beobachtet die Zeremonie. Sprecht erneut mit Malukaz, wenn die Zeremonie vorbei ist.", progress = "Die Verbindung mit dem Wolfgeist wiederherzustellen ist nur der Anfang meiner Reise, nicht das Ende.", completion = "Es ist unglaublich! Ich bin zu dieser Reise aufgebrochen, ohne auch nur die leiseste Ahnung zu haben, ob der Wolfgeist auf unsere Anrufung hin kommen würde. Und nun fühlt es sich an, als wäre er nie fort gewesen. Vielleicht war er das auch nie, {name}.\n\nVielleicht hat er darauf gewartet, dass die Orcs verstehen, was ihre Entscheidung bewirkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10792] = { id = 10792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor muss brennen!", description = "Der Klan des Blutenden Auges hat seine noble Herkunft verraten! Wir, die Orcs, die gekämpft haben und gestorben sind, um uns vor der Verderbtheit Mannoroths zu schützen, sehen in unseren bösen Vettern nur Schwäche und Unwürdigkeit... und dafür sollen sie brennen!\n\nGeht nach Zeth'Gor, ihre Bastion im Osten, und steckt ihre Gebäude in Brand. Tötet die Peons, um an ihre Fackeln zu kommen, entzündet diese an ihrer Schmiede und werft die brennenden Fackeln auf ihre Hütten, ihren Stall und ihre Kaserne. Brennt sie alle nieder und kehrt dann zu mir zurück!\n\nFür die Horde!", sourceObjective = "Tötet Peons des Blutenden Auges, um an ihre Fackeln zu kommen. Entzündet sie an der Schmiede von Zeth'Gor und werft die brennenden Fackeln auf die Gebäude von Zeth'Gor.", completion = "Hah! Ich konnte die Flammen über Zeth'Gor bis hierher sehen! Mögen unsere Feinde des Blutenden Auges zu Asche zerfallen und keinem wahren Orc mehr unter die Augen kommen!\n\nVielen Dank, {name}. Ihr habt geholfen, eine Beleidigung für den Geist eines jeden Orcs hinfort zu brennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10793] = { id = 10793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'zareqs Tagebuch: Vorboten des Krieges", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.", sourceObjective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.\n\nSucht ihn in einem Kristallgefängnis.", progress = "<General Auralion schwebt in der Mitte des Kristalls.>\n\nWa... Was tut Ihr hier?", completion = "Ihr habt ihren Eroberer getötet? Dann haben wir nicht viel Zeit...\n\nDas Purpursiegel besteht aus der Elite von Illidans Dienern. Sie stehen am oberen Ende der Befehlskette für Illidans Armeen außerhalb des Schwarzen Tempels. Diese Soldaten stehen in direktem Kontakt mit dem Verräter und führen seine Anweisung ohne Fragen zu stellen aus.\n\nSie sind diejenigen, die ohne mit der Wimper zu zucken einen Angriff auf diese Welt starten und dabei alles, was ihnen in Wege steht, dem Erdboden gleichmachen würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10794] = { id = 10794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurken der Zerschmetterten Hand", description = "{name}, es gibt Geheimnisse auf dieser Welt, die wir jetzt noch nicht verstehen. Die Zerschlagene Hand in Orgrimmar kann Euch zu einem dieser Geheimnisse führen: der Kunst, tödliche Gifte zu brauen. Tut einfach, was sie sagen, und Ihr werdet ihr Vertrauen gewinnen.\n\nUm nach Orgrimmar zu kommen müsst Ihr das Portal in Silbermond nach Unterstadt nehmen. Begebt Euch danach aus der Stadt hinaus und sucht den in der Nähe gelegnen Turm auf, bei dem die Zeppeline der Goblins ihre Fahrgäste aufnehmen. Fliegt von dort aus nach Orgrimmar, wo Ihr Shenthul in der Kluft der Schatten finden könnt.", sourceObjective = "Sprecht mit Shenthul in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10795] = { id = 10795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Dorgok", description = "Gut, ich habe Euch hier gesehen und wollte Euch in einer Angelegenheit von ziemlicher Wichtigkeit sprechen.\n\nMich ereilen Berichte, laut denen die Oger der Blutschläger einen Angriff gegen Sylvanaar und den Rabenwald planen. Wir wissen nicht, wer oder was sie dazu treibt, dies zu tun, aber ich bin entschlossen, ihren Plan im Keim zu ersticken!\n\nDie Angriffe sollen vom Lager der Blutschläger aus starten. Begebt Euch nach Nordwesten den Pfad aus dem Ruuanwald hinab in das Lager. Ich möchte, dass Ihr ihren Anführer Dorgok tötet!", sourceObjective = "Tötet Dorgok im Lager der Blutschläger.", completion = "Jetzt, da Dorgok tot ist, sind die Oger der Blutschläger ohne Anführer und hoffentlich verwirrt, bis ein neuer Anführer aus ihren Rängen gewählt wird.\n\nVielen Dank, {class}. Ich glaube, wir können nun ein wenig aufatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10796] = { id = 10796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet das Lager der Blutschläger!", description = "Ich habe gehört, dass Ihr uns im Kampf gegen die Oger bis jetzt mehr als stolz gemacht habt. Nun möchte ich Euch bitten, ihnen nochmals gegenüber zu treten. Ich möchte, dass Ihr das Lager der Blutschläger vernichtet!\n\nIhr gelangt dorthin, indem Ihr den nordwestlichen Weg aus den Ruuanwald hinab nehmt. Ihr findet die Oger am Ende des Weges.\n\nViel Glück, {class}!", sourceObjective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", completion = "<Der Leutnant nickt und scheint mit Eurer mörderischen Kühnheit sichtlich zufrieden.>\n\nIch bin beeindruckt, {name}. Euer Ruf scheint wohlverdient zu sein.\n\nJedes Mal, wenn einer dieser Oger zu Boden geht, sind wir einen Schritt näher daran, einen Feind loszuwerden, der uns niemals in Frieden lassen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10797] = { id = 10797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst der Gronn", description = "Aus Dorgoks leblosem Griff fällt ein Abzeichen in Form einer kleinen Statuette. Sie hat frappierende Ähnlichkeit mit einem Gronn.\n\nKommandant Haephus Steinwall im Ewigen Hain, den Weg im Osten hinauf, ist daran sicher sehr interessiert.", sourceObjective = "Bringt Gorgroms Gunst zu Kommandant Haephus Steinwall im Ewigen Hain im Schergrat.", progress = "Hallo, Junge! Was gibt es Neues?", completion = "Oh, das ist aber hübsch. Sieht ein bisschen aus wie diese Gronn, die die Oger der Speerspießer immer durch die Gegend scheuchen.\n\nKomisch, dass Ihr es in der Hand eines Anführers der Blutschläger gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10798] = { id = 10798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Baron einen Besuch abstatten", description = "Das sind schlechte Nachrichten. Gorgrom der Drachenfresser steckt hinter den Plänen der Blutschläger, Sylvanaar anzugreifen.\n\nIch weiß nicht, warum er sie manipuliert und nicht einfach die Speerspießer dazu benutzt. Aber wenn wir uns mit einem Gronn auseinandersetzen müssen, werden wir Hilfe benötigen.\n\nIch kenne einen Mann, der in allen möglichen Arten exotischer Magie bewandert ist. Sein Name ist Baron Zobelmähne. Er hält sich beim Zirkel des Blutes auf. Ihr könnt dorthin gelangen, indem Ihr den Weg im Nordwesten hinabsteigt und dann nach Südwesten durch die Schlucht geht.\n\nBittet ihn, uns eine Falle für den Gronn herzustellen.", sourceObjective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", completion = "Ah, ein Gesandter der gerühmten Allianz. Sagt mir, Lakai, warum seid Ihr es, der hierhergekommen ist und mich um dieses Ding bittet, und nicht Eurer illustrer Kommandant?\n\nKann es etwa sein, dass er Angst vor mir hat? Irgendetwas an Euch sagt mir, dass Ihr keine habt, aber ich weiß noch nicht, was das ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10799] = { id = 10799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Grabenschlucht", description = "Nun gut, ich werde diese Falle herstellen, aber zunächst möchte ich etwas dafür haben.\n\nZufälligerweise befindet sich ein Gronn in der Nähe im Besitz eines Gegenstands, den ich haben möchte. Ihr könnt ihm Euch jedoch nicht stellen, zumindest noch nicht.\n\nDaher werden wir ein Schlafpulver aus dem Gift der Krustenbohrer dieser Gegend herstellen.\n\nIhr findet sie in der Grabenschlucht im Südwesten. Bringt mir ein paar ihrer Drüsen und macht schnell!", sourceObjective = "Beschafft Euch 7 Giftdrüsen eines Krustenbohrers.", progress = "Habt Ihr die Giftdrüsen? Wenn nicht, dann hinfort mit Euch und wagt nicht, meine Zeit zu verschwenden, bevor Ihr sie habt!", completion = "Sehr gut, Ihr habt eine einfache, wenn nicht gar banale Aufgabe erfüllt. Nun gebt mir die Drüsen, damit ich den schwierigen Teil erledigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10800] = { id = 10800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Nacht, Gronn", description = "Ich habe mich mal wieder selbst übertroffen. Ich habe für Euch ein Schlafpulver erstellt, das Ihr Grulloc verabreichten könnt, dem Gronn, der besitzt, was ich möchte.\n\nGrulloc hält sich im Verfluchten Dunkel auf. Diese Gegend befindet sich am östlichen Rand von Drachenend auf der anderen Seite des Zirkels des Blutes.\n\nAn Eurer Stelle würde ich nicht lange zögern, sobald Ihr seinen Sack geschnappt habt. Die Wirkung des Staubs lässt schnell nach.", sourceObjective = "Beschafft Euch Grullocs Sack.", progress = "Ihr steht mir wieder gegenüber, {class}. Das muss bedeuten, dass Ihr den Sack unter Grullocs Nase weggeschnappt habt.", completion = "<Baron Zobelmähne lugt in den Sack des Gronns und scheint zufrieden.>\n\nSehr gut, Ihr habt Euren Teil der Abmachung gehalten. Nun werde ich Euren Kommandanten mit der Falle beschenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10801] = { id = 10801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist eine Falle!", description = "Es gibt nichts, was ich auf der Welt mehr hasse, als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nIch bin mir sicher, dass Ihr einen bestimmten Gronn in Sinn habt. Mir ist ganz gleich welcher, Hauptsache, Ihr tötet einen. Beeilt Euch und bringt die Falle zu Kommandant Steinwall.\n\nMein Rachedurst muss gestillt werden!", sourceObjective = "Bringt die Drachenfeuerfalle zu Kommandant Haephus Steinwall im Ewigen Hain im Schergrat.", progress = "Hat der Baron uns eine Falle gebaut? Eine, die stark genug ist, um einen Gronn zu töten?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10802] = { id = 10802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom der Drachenfresser", description = "Wir müssen den Ogern zeigen, dass sie sich nicht mit uns anlegen sollten! Wir müssen ihnen eine Nachricht zukommen lassen.\n\nReist nach Fels'mok und tötet die Oger dort. Hebt ihre Köpfe auf!\n\nGeht danach zu Gorgroms Altar und stellt die Falle auf. Daraufhin wird Gorgrom erscheinen. Ihr müsst versuchen, ihn in die Falle zu locken. Wenn er tot ist, stellt die Ogerköpfe als grausige Totems bei seinem Körper auf, damit die Oger ihren gefallenen Meister und ihre gefallenen Kameraden sehen können. Dann werden sie wissen, was man bekommt, wenn man sich mit uns anlegt!", sourceObjective = "Beschafft Euch 3 grausige Totems von den Ogern von Fels'mok. Benutzt danach Zobelmähnes Falle bei Gorgroms Altar, um Gorgrom den Drachenfresser zu rufen und zu töten.\n\nPlatziert die 3 grausigen Totems in der Nähe seines Körpers, wenn er gestorben ist.", progress = "Wurde die Nachricht schon überbracht?", completion = "Gut gemacht, {name}. Sehr gut gemacht!\n\nIch nehme an, dass wir nun nicht mehr von den Ogern und ihrem Herrn hören werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10803] = { id = 10803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemetzel in Fels'mok", description = "Ich weiß, dass wir vorhaben, Euch nach Fels'mok zu schicken. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichtemachen!\n\nFels'mok liegt im Westen. Reist nach Südwesten, überquert die Brücke und geht durch den Tunnel. Ihr findet sie auf der westlichen Seite des Rabenwalds.\n\n{name}, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok auslöscht!", sourceObjective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok.", completion = "<Leutnant Schönwetter grinst, als Ihr ihr von Euren Abenteuern in Fels'mok erzählt.>\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, {name}, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10804] = { id = 10804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundlichkeit", description = "Etwas hat sie aufgescheucht, {race}.\n\n<Mordenai zeigt auf die Netherdrachen, die über Euch fliegen.>\n\nSie kommen nicht einmal herunter, wenn ich sie füttere. Ich habe schon einige gesehen, die einfach zu Boden fielen. Sie sind vor Erschöpfung gestorben, noch bevor ihr Körper die Erde berührt hat.\n\nWir müssen sie retten! Die Felsspitzenschinder, die sich in der Nähe der Kristalle aufhalten, sind ihre natürliche Beute. Tötet die Schinder und nehmt ihre Kadaver. Legt einen Kadaver auf das Feld und verhaltet Euch äußerst ruhig. Solange Ihr keine hektischen Bewegungen macht, werden sie Euch auch nicht angreifen.", sourceObjective = "Mordenai bei den Netherschwingenfeldern im Schattenmondtal möchte, dass Ihr 8 ausgewachsene Drachen der Netherschwingen füttert.", progress = "Ich kann sie nicht alleine retten, {name}!", completion = "Ihr seid ein freundlicher und mitfühlender {race}, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10805] = { id = 10805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massaker in Gruuls Unterschlupf", description = "Ihr habt Euch als sehr nützlich erwiesen. Daher werde ich Euch in meinem persönlichen Kampf gegen Gruul und seine Söhne einsetzen.\n\nDer Stamm der Speerspießer steht in der Gunst der Gronn. Auch wenn Ihr ihre Reihen an anderen Orten bereits deutlich gelichtet habt, habt Ihr die Stärksten noch nicht erwischt.\n\nGruul lässt seinen Unterschlupf nur von den Kräftigsten unter den Ogern bewachen, und genau die müsst Ihr vernichten. Begebt Euch nach Norden durch die Dolchrachenklamm. An ihrem Ende findet Ihr Gruuls Unterschlupf.", sourceObjective = "Tötet 10 Vollstrecker der Speerspießer, 5 Kampfmagier der Speerspießer, 5 Verheerer der Speerspießer und ihren Anführer Fingrom.", completion = "Sehr gut. Ich habe eine weise Wahl getroffen, als ich Euch zur Speerspitze meines Kampfes gemacht habe. Ich schätze, es ist an der Zeit, die Dinge auf eine ganz neue Ebene zu tragen.\n\nErinnert Ihr Euch an den kleinen Leckerbissen, den Ihr Grolloc für mich unter der Nase weggeschnappt habt? Ihr werdet die Gelegenheit bekommen, ihn sinnvoll einzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10806] = { id = 10806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale", description = "Es ist für uns an der Zeit, uns Goc zu stellen, dem Herrn der Oger der Speerspießer. Es ist auch an der Zeit, dass ich mich in die Geschehnisse einmische und dem Gronn in seiner Todesstunde beiwohne.\n\nNehmt meinen Siegelring. Wenn Ihr zum Altar von Goc gelangt, benutzt ihn und ich werde Euch zu Hilfe kommen.\n\nZusammen werden wir Goc vernichten.", sourceObjective = "Benutzt Zobelmähnes Siegelring beim Altar von Goc und tötet Goc.", progress = "Bald werden alle Söhne des Gruul vernichtet sein.", completion = "Für jemanden von Eurem Schlag habt Ihr erstaunlich gut gekämpft. Es war mir eine Ehre, Euch an meiner Seite zu wissen. Meine Verwandlung muss Euch wohl ein wenig überrascht haben. Ich hoffe, ich habe Euch nicht allzu sehr erschreckt.\n\nWir sollten meine wahre Identität jedoch für uns behalten. Als Belohnung für Eure treuen Dienste biete ich Euch eines dieser Schmuckstücke an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10807] = { id = 10807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aschenzungen", description = "Der Aschenzungenstamm wird von allen Zerschlagenen gefürchtet. Er besteht aus den bösartigsten und blutrünstigsten Gestalten, die von Akama persönlich ausgewählt wurden. Sie sind so wild und rücksichtslos wie jeder Naga, Dämon oder Blutelf in Illidans Armee. Eine große Anzahl von ihnen wurde in den Ruinen von Baa'ri nördlich von hier stationiert. Begebt Euch dorthin und dezimiert ihre Zahl, bevor sie die Gelegenheit haben, uns anzugreifen.", sourceObjective = "Varen der Fordernde möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ehre den Sehern, {name}. Ihr habt den Willen des Lichts ausgeführt und Illidans Anhänger vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10808] = { id = 10808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Dunklen Rat in die Quere kommen", description = "Die Geister des Dunklen Rats versuchen, ein altes und mächtiges Übel durch ein Ritual, das bei den Lavabecken südlich des Basislagers der Sketh'lon durchgeführt werden soll, in diese Welt zu beschwören.\n\nGul'dans Magie vermischt mit ihrer eigenen! Und damit wollen sie diese Kreatur in unsere Welt rufen! Das dürfen wir nicht zulassen, {name}. Der Tod und die Zerstörung, die dieses Wesen in unsere Welt bringen würde, sind unvorstellbar!\n\nBringt den Stab zu dem Ort, an dem sie die Beschwörung durchführen wollen und benutzt seine Magie, um den Dunklen Rat ein für alle Mal aufzuhalten!", sourceObjective = "Tötet die Ritualisten des Dunklen Rats und benutzt Parshahs Stab, um das Beschwörungsritual des Dunklen Rats zu beenden. Kehrt danach zu Parshah in den Magmafeldern zurück.", progress = "Ist es vollbracht, {name}? Habt Ihr den Dunklen Rat davon abgehalten, das Ritual zu vollenden?", completion = "Ich habe jahrelang nach einem Weg gesucht, um den Dunklen Rat aufzuhalten. Ihr habt geschafft, wobei ich versagt habe. Die finsteren Rituale des Dunklen Rats werden nie wieder zu einer Bedrohung für uns.\n\nIch fühle mich oft schuldig, weil ich meine Kameraden vor all diesen Jahren verlassen habe, aber nun weiß ich endlich, dass es die richtige Entscheidung war. Hätte mein Gewissen damals nicht zu mir gesprochen, wäre ich nun vielleicht ein Schatten unter ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10809] = { id = 10809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Worgmeister Kruush", description = "Auf dem Anschlag steht geschrieben:\n\n\"Worgmeister Kruush führt die Worgreiter des Blutenden Auges an. Da seine Reiter große Opfer unter den Versorgungskarawanen des Rückenbrecherpostens gefordert haben, wurde ein Preis auf seinen Kopf ausgesetzt.\"\n\n\"Späher berichten, dass er in Zeth'Gor gesehen wurde. Der Held, der den abgetrennten Kopf des Übeltäters zu mir bringt, wird den Dank der Horde sowie ein großzügiges Kopfgeld erhalten.\"\n\nGezeichnet: Hauptmann Nachtheul", sourceObjective = "Tötet Worgmeister Kruush und bringt seinen Kopf zu Hauptmann Nachtheul im Rückenbrecherposten.", progress = "Berichtet, {name}. Ist das Blut des Blutenden Auges da auf Eurem Ärmel? Ich hoffe doch!", completion = "Ihr habt also den Tunichtgut Kruush erschlagen! Gut gemacht, {name}! Sehr gut! Sein Tod wird seinen verfluchten Worgreitern die Giftzähne ziehen! Ich hoffe, Ihr habt auch ein paar von ihnen erledigt, als Ihr Euren kleinen Ausflug nach Zeth'Gor gemacht habt!\n\nHier ist Eure Belohnung. Ihr habt sie Euch verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10810] = { id = 10810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beschädigte Maske", description = "Während ihr die beschädigte Maske betrachtet, hört Ihr Geräusche aus ihrem Inneren kommen. Wenn die Maske nicht beschädigt wäre, könntet Ihr die Geräusche deutlicher hören.\n\nO'Mally Zapschnapper im Ruuanwald könnte sie vielleicht reparieren.", sourceObjective = "Bringt die beschädigte Maske zu O'Mally Zapschnapper in den Ewigen Hain im Schergrat.", progress = "Geht mir nicht auf die Nerven! Könnt Ihr nicht sehen, dass ich dabei bin, mysteriöse Kräfte zu entfesseln?", completion = "Ah, was habt Ihr denn da? Lasst mich das mal genauer ansehen, {class}. Ja, ja... es ist genau das, was ich dachte. Lasst mich die Maske für Euch reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10811] = { id = 10811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Neltharaku auf", description = "Ihr Patron schwebt hoch oben in den Lüften, {name}. Vielleicht hat die Freundlichkeit, die Ihr seinen Kindern gegenüber gezeigt habt, sein Herz bewegt. Sucht Neltharaku auf und bittet ihn um Hilfe. Zusammen könnt Ihr vielleicht die Not der Netherschwingendrachen beenden.\n\n<Mordenai zeigt in den Himmel.>\n\nFliegt hoch, {class}.", sourceObjective = "Sucht Neltharaku, den Patron des Drachenschwarms der Netherschwingen auf.", completion = "Meine Kinder haben mir von Eurer heldenhaften Tat erzählt, {race}. Es gibt noch mehr, was Ihr tun könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10812] = { id = 10812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geheimnisvolle Maske", description = "Gut, jetzt sollte sie funktionieren. Was das ist, fragt Ihr? Nun, es ist ein Kommunikationsgerät. Diese Schafsköpfe kommunizieren so miteinander. Ihr wisst schon, die Brennende Legion! Ich würde Euch empfehlen, die Maske zu Wildfürst Antelarion zu bringen. Er geht dort drüben auf und ab. Immer in Bewegung!\n\nNun los mit Euch! Er versucht schon eine ganze Weile eine von den Masken in die Finger zu bekommen.", sourceObjective = "Bringt die geheimnisvolle Maske zu Wildfürst Antelarion in den Ewigen Hain im Schergrat.", progress = "Ich traue meinen Augen nicht.", completion = "Diese Maske, die Ihr da in den Händen haltet, ist eine Gasmaske der Teufelsbrut! Und wie es aussieht, ist sie nicht beschädigt! Der Ärger, den wir damit im Konstruktionslager: Groll anrichten können, ist grenzenlos! Habt Ihr Lust, uns dabei zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10813] = { id = 10813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Grillok", description = "{name}, Ihr habt im Nest der Orcs des Blutenden Auges, im gefürchteten Zeth'Gor, Euren Heldenmut bewiesen und überlebt! Vielleicht seid Ihr stark genug, um mir zu helfen, denn ich werde in den Geist ihres finstersten Hexers blicken, Grillok!\n\nNehmt diesen Splitter. Benutzt ihn, um ein Auge von Grillok zu behexen und bindet es an Euch. Kehrt dann zu mir zurück und nähert Euch meinem Kessel... er wird das Auge anziehen.\n\nGeht, {name}. Und seid auf der Hut! Ein Auge von Grillok wird Euch an Eure Feinde verraten, wenn es auch nur die geringste Gelegenheit dazu bekommt!", sourceObjective = "Benutzt Zezzaks Splitter, um ein Auge von Grillok zu fangen und nähert Euch damit Zezzaks Kessel. Bringt den Splitter zu Zezzak zurück, wenn Ihr das Auge dem Kessel übergeben habt.", progress = "Die Orcs des Blutenden Auges waren einst starke Verbündete... und nun sind sie noch stärkere Feinde.", completion = "Ich stehe tief in Eurer Schuld, {name}. Ihr habt ein weiteres Mal über Zeth'Gor triumphiert und seine Dunkelheit nahe an Euer Herz gelassen. Ich werde das Auge untersuchen und damit hoffentlich die Geheimnisse seines Meisters Grillok lüften.\n\nHoffentlich kann es seine Magie nicht länger einsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10814] = { id = 10814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharakus Geschichte", description = "Ich habe Informationen, die Euch vielleicht weiterhelfen können. Bitte hört Euch an, was ich zu erzählen habe.", sourceObjective = "Sprecht mit Neltharaku und hört Euch seine Geschichte an.", completion = "Werdet Ihr uns also helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10815] = { id = 10815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'zareqs Tagebuch: Vorboten des Krieges", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.", sourceObjective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10816] = { id = 10816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückforderung geheiligten Bodens", description = "Ihr habt Eure Arbeit bei den Zerschlagenen in Baa'ri gut gemacht, {name}. Wollen wir mal sehen, wie Ihr gegen Illidans gefürchtetste Armee besteht.\n\nDie Terrasse von Ata'mal war einst eine geheiligte Stätte, an der wir die Kristalle von Ata'mal benutzten, um spirituelle Zeremonien durchzuführen. Nun ist dieser Orts von den Höllenorcs des Schattenmondklans besetzt worden.\n\nWir hatten guten Grund zur Annahme, dass sie einen Kristall von Ata'mal in der Nähe versteckt halten, aber unsere magische Beobachtung dieses Ortes lieferte kein Ergebnis. Dennoch sind die Orcs auf unserem geheiligten Boden eine Schmach, die wir nicht tolerieren können.", sourceObjective = "Verteidiger Aluumen möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Aufgaben für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ausgezeichnete Arbeit, {class}. Möge das Licht Euch beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10817] = { id = 10817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Vergeltung", description = "Ihr habt Euch im Kampf gegen die Zerschlagenen der Aschenzungen tapfer geschlagen, {name}. Wenn Ihr bereit seid, habe ich eine weitere Herausforderung für Euch.\n\nVor nicht allzu langer Zeit wurde das Sanktum der Sterne Opfer eines gewaltigen Angriffs durch Illidans Höllenorcs.\n\nWir haben herausgefunden, dass die Schattenmondorcs, die die Terrasse von Ata'mal behausen, dieses Verbrechen verübt haben.\n\nZeigt ihnen, dass man sich besser nicht mit den Sehern anlegen sollte!", sourceObjective = "Varen der Fordernde möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ihr habt meinen höchsten Respekt verdient, {name}.\n\nEinen Höllenorc alleine zu töten ist schon keine leichte Aufgabe. Eine ganze Meute von ihnen zu töten ist, nun... heroisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10818] = { id = 10818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähne verlangt nach Euch", description = "{name}, während Ihr denen da draußen richtig die Hölle heiß gemacht habt, hat Baron Zobelmähne seinen Drachen mit einer Nachricht hierher geschickt.\n\nEr hat nach Euch persönlich gefragt. So wie ich es verstanden habe, möchte er, dass Ihr seinen eigenen Kampf gegen die Gronn weiterführt.\n\nIch schätze, dass Ihr wohl die geeignetste Person in der ganzen Scherbenwelt seid, um ihm dabei zu helfen, aber an Eurer Stelle würde ich ein paar Freunde bitten, Euch zum Zirkel des Blutes zu begleiten.", sourceObjective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", completion = "Ah, wie ich sehe habt Ihr beschlossen, Euch ganz schön Zeit zu lassen, bis Ihr meinem Aufruf Folge geleistet habt.\n\nWie auch immer, ich hatte genug Zeit, um an meinen Racheplänen zu feilen, und Ihr sollt in der kommenden Schlacht mein Vollstrecker sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10819] = { id = 10819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gasmaske der Teufelsbrut", description = "Ich habe eine ganz besondere Aufgabe für Euch, {name}. Ich möchte, dass Ihr Euch in das Konstruktionslager: Groll östlich von hier einschleicht. Ihr werdet die Gasmaske der Teufelsbrut tragen müssen, wenn Ihr das Lager betretet, um den Legionskommunikator zu suchen. Sobald Ihr das Kommunikationsgerät gefunden habt, benutzt es. Sprecht mit demjenigen, der sich auf der anderen Seite meldet.\n\nWenn alles klappt, könnt Ihr dem Dämon ein Märchen auftischen! Versucht, ihm zu erzählen, dass im Konstruktionslager: Groll ein Aufstand ausgebrochen ist.\n\nViel Glück, {class}.", sourceObjective = "Setzt die Gasmaske der Teufelsbrut auf und benutzt den Legionskommunikator im Konstruktionslager: Groll im Schergrat.\n\nBereitgestellter Gegenstand:", completion = "Was soll das bedeuten? Niemand ruft mich! Sprecht, oder ich werde Euch für immer zum Schweigen bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10820] = { id = 10820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täuscht den Feind", description = "Mit jedem Moment, in dem ich Stille höre, rückt Ihr dem Tod ein Stückchen näher! SPRECHT!\n\nWas? Das Lager revoltiert? Das kann nicht wahr sein! Meine Diener würden es niemals wagen, meine Autorität zu untergraben.\n\nNun gut, jeder Einzelne von ihnen wird für diesen Verrat bezahlen... teuer bezahlen! Bringt sie alle zum Schweigen! Meldet Euch bei mir zurück, wenn Ihr meinen Befehl ausgeführt habt, oder ich werde mich um Euch kümmern.", sourceObjective = "Tötet 4 Knechte der Schicksalsschmiede und 4 Ingenieure der Schicksalsschmiede.", completion = "Das wird ihnen sicher zeigen, dass sie besser tun sollten, was ich ihnen sage...\n\nÜbrigens... wo ist Schicksalsrufer? Warum habt Ihr mir von dieser Revolte berichtet und nicht sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10821] = { id = 10821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid gefeuert!", description = "Schicksalsruferin hat nichts gegen den Aufstand unternommen? Wie kann sie es wagen! Sie hat schon seit einer Weile versucht, meine Autorität zu untergraben. Doch zum allerletzten Mal! Ihr müsst sie rufen und persönlich zur Verantwortung ziehen.\n\nIhre Grollwachen tragen die Schlüssel bei sich, mit denen sie ins Konstruktionslager: Groll gerufen werden kann. Beschafft Euch die fünf Schlüssel und aktiviert die fünf Obelisken der Legion. Die Obelisken schalten sich nach kurzer Zeit wieder ab, also seht zu, dass Ihr sie alle gleichzeitig aktiviert. Und denkt daran: die Grollwachen tragen noch mehr Schlüssel bei sich.", sourceObjective = "Tötet Schicksalsruferin.", completion = "Das sind wirklich großartige Nachrichten, {name}. Ich hätte es mir nicht besser wünschen können. Eure Dienste gegenüber meinem Volk sind sehr geschätzt. Bitte wählt Euch einen dieser Gegenstände aus.\n\nEuer Name wird für immer in den Herzen unseres Volkes klingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10822] = { id = 10822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Siegel des Sonnenzorns" }
quests[10823] = { id = 10823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Siegel des Sonnenzorns" }
quests[10824] = { id = 10824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Sonnenzorns", description = "Das Überleben der Seher hängt davon ab, ob wir es schaffen, mehr Rekruten zu sammeln als Kael'thas. Jeder Pilger aus Quel'Thalas, der sich auf seine Seite schlägt, bringt ihn einen Schritt näher an den Sieg. Und das bedeutet das Gegenteil für uns.\n\nBald werden uns jedoch die Rekruten ausgehen und es wird darauf hinauslaufen, wer den anderen schneller tötet. Beweist Euch gegenüber den Sehern und bringt mir die Siegel des Sonnenzorns der höherrangigen Blutelfen, die im Bunde mit Illidan und Kael'thas stehen. Ihr findet sie bei der Stätte der Mondfinsternis im Westen und in den Ruinen von Karabor im Nordosten.", sourceObjective = "Kampfmagierin Vyara beim Sanktum der Sterne möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Los, {name}. Sprecht.", completion = "Kaels Armee des Sonnenzorns ist sehr gut ausgebildet. Ausgezeichnete Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10825] = { id = 10825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kugellose Wahrheit", description = "Diese merkwürdige, magische Kugel fällt aus dem Federkleid des Arakkoa.\n\nSie ist von einem unheimlichen violetten Leuchten umgeben und pulsiert zu einem unhörbaren Takt. Sie in der Hand zu halten gibt Euch ein unangenehmes Gefühl, daher packt Ihr sie schnell in Eure Tasche.\n\nVielleicht würde Baumhüter Chawn im Ruuanwald im Westen, jenseits des Tunnels und der Brücke des Wyrmschädels, sie gerne untersuchen?", sourceObjective = "Bringt die Kugel der Grishna zu Baumhüter Chawn in den Ewigen Hain im Schergrat.", progress = "{class}, könnt Ihr das spüren? Ich fühle, dass etwas Unnatürliches und Böses in der Nähe ist.", completion = "Ja, es ist die Kugel, die Ihr da habt! Merkwürdig, sie scheint von den Arakkoa zu stammen. Wart Ihr kürzlich in Grishnath?\n\nAh, das erklärt das Ganze. Aber ich frage mich, welchem teuflischen Zweck dieses Objekt dient. Obwohl das Böse eindeutig darin schlummert, scheint sie doch mit der Natur verbunden zu sein.\n\nBitte erlaubt mir zu versuchen, sie zu aktivieren. Das Böse darin ist so stark, es erinnert mich an etwas...", sourceObjectiveStatus = "unverified-source-field" }
quests[10826] = { id = 10826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Male des Sargeras", description = "Inzwischen sollte Euch klar geworden sein, dass wir der Brennenden Legion und ihren Dienern feindlich gesonnen sind.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, dann bringt mir die Insignien der hochrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Hier im Schattenmondtal könnt Ihr eine große Ansammlung der Legion weit im Westen in der Feste der Legion und der Todesschmiede finden.", sourceObjective = "Bringt 10 Male des Sargeras zu Herold Saronen im Schattenmondtal.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, {name}?", completion = "Ihr seid sehr mutig, Freund. Mögen alle wissen, dass Ihr ein wahrer Freund der Priesterschaft seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[10827] = { id = 10827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Male des Sargeras" }
quests[10828] = { id = 10828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Male des Sargeras" }
quests[10829] = { id = 10829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baumriese muss es wissen", description = "Das ist erschütternd! Die Arakkoa bewirken, dass die Urtume und Beschützer von bösen Geistern besessen werden!\n\nEs gibt jedoch ein Urtum, das auf gar keinen Fall davon betroffen sein kann. Sein Name ist Baumriese. Wenn wir die Bäume des Rabenwaldes retten wollen, müsst Ihr sofort zu ihm gehen!\n\nBegebt Euch in den Rabenwald. Ihr findet ihn an der Weggabelung kurz hinter Grishnath.", sourceObjective = "Sprecht mit Baumriese, ein Urtum der Lehren, das im Rabenwald im Schergrat lebt.", completion = "Grüße, kleiner {race}. Die Vögel in meinen Zweigen haben mir zugeflüstert, dass Ihr kommen würdet.\n\nIhr seid hier, um die Bäume des Waldes von ihrer Besessenheit zu heilen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10830] = { id = 10830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exorzismus der Bäume", description = "Die Grishna sind dafür verantwortlich, dass die Laubbärte und Steinborken von bösen Koikoigeistern übernommen werden.\n\nWir müssen die Bäume retten, sonst ist der Rabenwald bald verloren!\n\nKombiniert die Macht einer Kugel von Grishnath, die überall in Grishnath zu finden sind, mit einem Terrorfederkiel eines Terrorraben.\n\nBenutzt die dadurch entstandene Exorzismusfeder, um die Koikoigeister hervorzulocken und so schnell wie möglich umzubringen. Die Steinborken sind für dieses Ritual zu stark, aber wenn Ihr genügend Laubbärte befreit, werden auch sie frei sein.", sourceObjective = "Sammelt 5 Kugeln von Grishnath und 5 Terrorfederkiele und stellt daraus Exorzismusfedern her. Benutzt die Federn, um 5 Koikoigeister von den Laubbärten des Rabenwaldes zu exorzieren und zu töten.", progress = "Das Böse, das den Bäumen innewohnt, breitet sich auf die gesamte Natur des Waldes aus.\n\nIhr müsst schnell handeln, {name}, bevor es zu spät ist!", completion = "Das Böse verschwindet aus dem Rabenwald! Könnt Ihr es fühlen, {name}?\n\nIhr habt uns und alle Wildtiere hier vor der unweigerlichen Zerstörung gerettet, kleines Wesen!\n\nFür solche Gelegenheiten trage ich vier magische Ringe in meinen Zweigen und verschenke sie, wenn ein Held sich erhebt, um eine große Tat zu vollbringen.\n\nIhr seid solch ein Held! Im Namen des gesamten Rabenwaldes danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10831] = { id = 10831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Mondstoffschneider wird", description = "Ich kann Euch die Kunst des Mondstoffschneiderns beibringen, wenn Ihr möchtet. Wenn Ihr Euch auf die Mondstoffschneiderei spezialisiert, werdet Ihr bei der Herstellung von Urmondstoff den doppelten Ertrag erhalten und Zugang zu mehreren exklusiven Mustern bekommen. Dazu müsst Ihr nur einen einfachen Test bestehen.\n\nDer Test besteht darin, eine kleine Probe Urmondstoff im Mondbrunnen der Zuflucht des Cenarius herzustellen. Ich werde Euch alle Materialien, die Ihr dafür benötigt, zur Verfügung stellen. Bringt mir die Probe, wenn Ihr sie fertig gestellt habt, damit ich sie beurteilen kann.Ihr erlernt:", sourceObjective = "Benutzt das magieerfüllte Netherstoffstück während Ihr im Mondbrunnen der Zuflucht des Cenarius steht, um eine Urmondstoffprobe herzustellen. Bringt die fertige Urmondstoffprobe zu Nasmara Mondweise im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10832] = { id = 10832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Zauberfeuerschneider wird", description = "Ich kann Euch die Kunst der Zauberfeuerschneiderei beibringen, aber seid gewarnt, es ist eine gefährliche Kunst.\n\nDie Herstellung von Zauberstoff im Nethersturm lockt mächtige Nethergespenster an. Ich bin auf der Suche nach einem Weg, um den Effekt zu mildern, aber dazu brauche ich noch mehr Essenzen der Nethergespenster für meine Forschungen.\n\nBringt dieses Signal zum Nethersturm und benutzt es, um ein Nethergespenst zu rufen. Bringt mir seine Essenz, dann werde ich Euch unterrichten. Als Zauberfeuerschneider werdet Ihr doppelt so viel Stoff erhalten und Zugang zu exklusiven Mustern bekommen.Ihr erlernt:", sourceObjective = "Bringt eine Probe einer Nethergespenstessenz zu Gidge Spruchwirker im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10833] = { id = 10833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Schattenzwirnschneider wird", description = "Wenn Ihr Euch auf die Schattenzwirnschneiderei spezialisiert, werdet Ihr doppelt so viel Schattenstoff wie ein gewöhnlicher Schneider herstellen können und Zugang zu exklusiven Mustern erhalten.\n\nNatürlich kann jeder Schneider den Altar der Schatten benutzen, aber ein Schattenzwirnschneider hat eine tiefere Verbindung zu dem Altar und entfesselt dadurch Mächte, die sich nur wenige vorstellen können.\n\nBringt diesen Kristall in das östliche Schattenmondtal und sucht den Netherschwingenpass, der von den Netherschwingenfeldern aus nach Süden führt. Nahe am Ende der Welt findet Ihr den Altar der Schatten. Benutzt dort den Kristall.Ihr erlernt:", sourceObjective = "Benutzt den Kristall der tiefen Schatten in der Nähe des Altars der Schatten, um Eure Verbindung zu dem Altar zu stärken. Kehrt danach zu Andrion Dunkelweber im Unteren Viertel in Shattrath zurück.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10834] = { id = 10834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillok 'Finsterauge'", description = "Grillok Finsterauge hat einen Teil von sich den dunklen Mächten verpfändet und dafür große Macht erhalten. Sein verlorenes Auge brennt nun in irgendeiner teuflischen Grube als Schmuckstück eines Dämons... und die Klappe, die seinen Verrat versteckt, hat ihr ganz eigenes dunkles Geheimnis.\n\nBringt mir Grilloks Augenklappe, {name}, und ich werde Euch fürstlich für Eure Dienste belohnen.", sourceObjective = "Tötet Grillok Finsterauge und bringt Grilloks Augenklappe zu Zezzak im Rückenbrecherposten.", progress = "Die Bösartigkeit der Orcs des Blutenden Auges kennt keine Grenzen und wird nur noch von der ihrer Vettern der Zerschmetterten Hand übertroffen.", completion = "Ah ja. Ich frage mich, ob Grillok in seinen dunklen, dunklen Träumen immer noch mit seinem verlorenen Auge verbunden ist, wie jemand, der eine Hand oder ein Bein in der Schlacht verloren hat...\n\nAuch ich werde davon träumen. Und wenn das Schicksal auf unserer Seite steht, werden wir dadurch erfahren, was Grillok und die Orcs des Blutenden Auges dazu gebracht hat, sich den Dämonen zu unterwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10835] = { id = 10835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apotheker Antonivich", description = "{name}, ich habe einen vorläufigen Bericht über meine Befunde bezüglich der Orcs des Blutenden Auges angefertigt. Mein Kollege in Thrallmar, Apotheker Antonivich, will ihn sicher gerne lesen. Auch er befasst sich mit dem Phänomen der Höllenorcs und hofft verhindern zu können, dass eine solche Tragödie auch unseren orcischen Verbündeten zustoßen könnte.\n\nBringt diesen Bericht zu ihm. Ich werde in der Zwischenzeit weiter das Blut, das Ihr mir gebracht habt, untersuchen. Wenn das Glück auf unserer Seite ist, können wir die Ursache für das Leiden der Höllenorcs herausfinden.", sourceObjective = "Bringt Albrecks Befund zu Apotheker Antonivich nach Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Guten Tag, {name}. Wie gefällt Euch Euer Aufenthalt auf der Höllenfeuerhalbinsel? Ich bin mir sicher, dass er sehr ergiebig ist...", completion = "Ah, ein Bericht von Albreck? Sehr gut. Die königliche Apothekervereinigung versucht verzweifelt herauszufinden, wie die Orcs zu Höllenorcs geworden sind. Ihr Verrat ist unverzeihlich... und wir müssen sicherstellen, dass unsere Orcfreunde für alle Zeit vor dieser Verderbnis sicher sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10836] = { id = 10836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwanderung der Festung des Drachenmals", description = "Ich brauche Zeit, um einen Plan zu entwickeln, mit dem ich meine Kinder und mein Weibchen retten kann. Ihr werdet mir diese Zeit beschaffen, <Sterblicher/Sterbliche>.\n\nReist zur Festung des Drachenmals am östlichen Ende der Netherschwingenfelder und vernichtet alle Orcs des Drachenmals, die Ihr finden könnt. Das daraus resultierende Chaos und die Verwirrung sollte ihre Pläne maßgeblich beeinflussen.\n\nDoch seid auf der Hut. Einige meiner Art sind bereits von den Orcs des Drachenmals verderbt worden. Für sie besteht die einzige Erlösung im Tod. Ihr habt meine Erlaubnis, auch ihr Leben zu beenden.", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 15 Orcs des Drachenmals tötet.\n\nSämtliche Orcs des Drachenmals in der Festung des Drachenmals kommen dafür in Frage.", completion = "Gut gemacht, {name}. Ich habe einen Weg gefunden, wie wir die versklavten Drachen in der Festung des Drachenmals befreien können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10837] = { id = 10837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Netherschwingenscherbe!", description = "Ich glaube, dass ich die Netherrankenkristalle mit meiner eigenen Essenz erfüllen kann. Die Macht in diesen magieerfüllten Kristallen sollte ausreichen, um die versklavten Drachen aus den Klauen ihrer Meister zu befreien.\n\nReist zur Netherschwingenscherbe, einer Insel am zerbrochenen Rand des Schattenmondtals im Südosten. Auf der Netherschwingenscherbe könnt Ihr die Netherrankenkristalle finden. Kehrt zu mir zurück, wenn Ihr genügend Kristalle gefunden habt, um Eure Taschen damit zu füllen.\n\nUnd Vorsicht, {name}. Der Drachenmalklan hat sich nun auf der Insel niedergelassen.", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 12 Netherrankenkristalle auf der Netherschwingenscherbe sammelt.", progress = "Ich brauche Netherrankenkristalle.", completion = "<Neltharaku nimmt Euch die Kristalle ab.>\n\nIch werde nun die Kristalle mit meiner Magie erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10838] = { id = 10838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dämonische Seher", description = "Der dämonische Seher ist nun bereit. Bringt ihn hinter die Höllenfeuerzitadelle, in das Höllenfeuerbecken, und platziert ihn dort auf dem Boden. Er wird sich dann selbst auf die Höllenfeuerzitadelle einstellen. Sprecht danach mit dem Seher und schreibt auf, was Ihr erfahrt. Bringt Euren Aufschrieb zu mir...\n\nGeht, {name}, aber erst, wenn Ihr bereit seid. Die Höllenfeuerzitadelle wird ohne Zweifel die Anwesenheit des Sehers entdecken und Wärter schicken, um ihn zu vernichten!", sourceObjective = "Benutzt den dämonischen Seher im Höllenfeuerbecken, wartet, bis er sich eingestellt hat und führt dann eine Messung durch.\n\nBringt den dämonischen Seher und die Messungen des dämonischen Sehers zu Apotheker Antonivich in Thrallmar.", progress = "Habt Ihr die Messung? War Euer Auftrag mit dem dämonischen Seher erfolgreich?", completion = "Ihr habt die Messung? Ausgezeichnet. Ich bin mir sicher, dass diese Daten sich für unsere Forschungen als unersetzlich erweisen werden. Ich werde sie gleich an Apothekerin Zelana und Apotheker Albreck weiterleiten.\n\nIhr solltet stolz auf Euch sein, {name}. Eure Stärke und Euer Mut steht außer Frage... genauso wie Eure Leistungen gegenüber der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10839] = { id = 10839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelstein des Skithverstecks", description = "Das Skithversteck liegt nordwestlich der Karawane und südlich von Shattrath in einem Versteckten Hain im Wald. Man sagt, dass die Kolonie von Skettis dort einen bösartigen Altar der Verehrung errichtet hat. Wenn die Arakkoa der Skith jemals erlöst werden wollen, muss Terokks Dunkelstein zuerst geläutert werden.\n\nNehmt diese Rute der Läuterung und werft sie auf den Dunkelstein. Da sie von A'dal selbst gesegnet wurde, sollte die Reinheit der Rute stark genug sein, um den Dunkelstein zu reinigen. Nun geht. Möge das Licht über Euch wachen.", sourceObjective = "Benutzt die Rute der Läuterung bei Terokks Dunkelstein im Skithversteck und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste zurück.", progress = "Die Dunkelheit umgibt uns. Was habt Ihr mir aus dem Skithversteck zu berichten?", completion = "Ich habe bis hierher die Explosion hören können. Nicht mit meinen Ohren, sondern mit meinem Herzen.\n\nWenn die Berührung des gesegneten Naaru A'dal nicht ausreicht, um die Arakkoa zu erlösen, dann kann nichts auf der Welt das schaffen. Diejenigen, die ihre Seele nicht dem Licht ausgeliefert haben, sind nichts als Diener des Bösen.\n\nSie müssen vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10840] = { id = 10840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grab des Lichts", description = "Im Osten, unter dem versengten Sand, befindet sich das Grab des Lichts. Das Grab ist eine verlorene Ruhestätte unserer Toten. Bevor unsere Karawane überfallen wurde, war ich auf dem Weg zu dem Grab, um es von bösen Geistern zu befreien.\n\nIch hatte ja keine Ahnung, dass es bereits von einem anderen Übel heimgesucht wird. Sogar jetzt noch plündern die Astralen die Körper unsere Gefallenen, um an die Schmuckstücke und Andenken zu kommen, die den Toten vor Jahrhunderten mit ins Jenseits gegeben wurden.\n\nAber ich kann nichts dagegen unternehmen, solange unsere Karawane ums Überleben kämpft.", sourceObjective = "Hohepriester Orglum möchte, dass Ihr zum Grab des Lichts reist und 10 astrale Nethermanten und 10 astrale Brandschatzer tötet. Kehrt danach zu ihm zurück. Zu finden ist er bei der Flüchtlingskarawane.", completion = "Hier in der Wildnis der Scherbenwelt sind wir schwach. Nur wenige Helden verteidigen unsere Rechte, aber Ihr habt ihnen gezeigt, dass sie sich fürchten müssen, {class}. Ich glaube nicht, dass die Astralen Euren starken Arm so schnell vergessen werden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10841] = { id = 10841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der rachsüchtige Herold", description = "Geht in das Grab des Lichts und aktiviert das Gerät.", sourceObjective = "Aktiviert das Gerät.", sourceObjectiveStatus = "unverified-source-field" }
quests[10842] = { id = 10842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachsüchtige Seelen", description = "Das Grab des Lichts wurde vom Schattenrat verderbt und die toten Draenei wurden zu verfluchten Geistern, die von Zorn erfüllt sind und vor Hass auf die Lebenden brennen.\n\nBetretet das Grab", sourceObjective = "Hohepriester Orglum möchte, dass Ihr in das Grab des Lichts reist und 5 rachsüchtige Draenei besiegt.", completion = "Ich danke Euch im Namen der gequälten Seelen, die Ihr befreit habt, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10843] = { id = 10843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seit ich denken kann...", description = "Schon seit ich denken kann haben wir gegen die Oger der Speerspießer gekämpft.\n\nWir haben es geschafft, sie so weit zurück zu drängen, dass sie nun nur noch im Außenposten der Speerspießer vertreten sind. Dieser Außenposten befindet sich dort, wo Ihr herkommt, am südwestlichen Rand des Messergrats.\n\nBeweist mir Euren Wert, indem Ihr ihren Anführer Gnosh Brognat tötet.\n\nWollen wir mal sehen, aus welchem Holz Ihr geschnitzt seid, wenn es darum geht, die Oger zu bekämpfen.", sourceObjective = "Tötet Gnosh Brognat, den Anführer der Oger im Außenposten der Speerspießer.", completion = "<Leoroxx mustert Euch aufmerksam.>\n\nGnosh Brognats Tod ist ein Segen für alle Mok'Nathal. Das ist gut für Euch.\n\nMal schauen, ob Ihr immer noch so heldenhaft seid, wenn wir die Messlatte etwas anheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10844] = { id = 10844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager: Groll" }
quests[10845] = { id = 10845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Brutmutter", description = "Meine Jäger sind gerade von einer Aufklärungsmission im Singenden Bergrücken zurückgekehrt. Wie es aussieht hat sich die Zahl der Netherdrachen, die die Kristalle dort heimsuchen, deutlich vergrößert. Bald werden sie sich weiter ausbreiten!\n\nDa Ihr Euch als <fähiger/fähige:c> {class} herausgestellt habt, wollen wir einmal sehen, ob Eure Fertigkeiten einem ausgewachsenen Drachen gewachsen sind.\n\nIhr findet den Singenden Bergrücken, indem Ihr nach Süden durch die Schuppenflügelbank geht. Tötet ihre Brutmutter, Unheilschwinge.", sourceObjective = "Tötet Unheilschwinge.", completion = "Nein! Ihr habt Unheilschwinge getötet? Vielleicht habe ich mich in Euch getäuscht, {class}.\n\nVielleicht.\n\nDennoch habt Ihr die Anführer der drei größten Bedrohungen für unser Volk erschlagen. Darauf könnt Ihr stolz sein.\n\nIch werde Euch ein Zeichen meiner Wertschätzung geben, aber lasst es Euch nicht zu Kopf steigen. Ihr habt immer noch keine Ahnung davon, was es bedeutet, ein Mok'Nathal zu sein. Vielleicht werden wir immer noch auf Eure Fähigkeiten zurückkommen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10846] = { id = 10846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verständnis für die Mok'Nathal", description = "<Leoroxx schaut Euch mit einem Blick an, der Euch das Blut in den Adern gefrieren lässt.>\n\nIhr kommt zu den Mok'Nathal, aber Ihr versteht uns nicht. Ihr versteht unseren Kampf um Leben oder Tod nicht.\n\nWenn Ihr uns verstehen wollt, müsst Ihr Euch diesem Kampf aussetzen.\n\nIm Süden findet Ihr die Arakkoa der Vekh'nir. Sie halten eine Gruppe von Ogern in den Höhlen, die als Trogmas Besitz bekannt sind, als Sklaven. Dort findet Ihr auch ihren Anführer Vekh.\n\nTötet ihn!", sourceObjective = "Tötet Vekh, Anführer der Arakkoa der Vekh'nir.", completion = "Die Vekh'nir sind noch die harmlosesten unserer Feinde.\n\nIhr habt also einen übergroßen Vogel getötet. Das macht Euch noch lange nicht zu einem wahren {class}. Das lässt Euch auch nicht unser Wesen verstehen.\n\nAber es ist ein Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10847] = { id = 10847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Skettis", description = "Von den Klippen von Skettis zieht Unheil heraus.\n\nDas Schicksal meines Volkes, der Arakkoa, wird von einem unaussprechlichen Bösen verschleiert. Schon zu oft haben wir schwarze Magie für üble Taten eingesetzt. Durch A'dal erfuhren wir vom Licht und von der Erlösung.\n\nTerokk überwacht seine Kolonien von Skettis aus mithilfe von Sphären, die er mit seiner schwarzen Kunst verzaubert hat. Stehlt diese Augen aus dem Reskkversteck und dem Shienorversteck im nördlichen Terokkar. Ich möchte sehen können, was Terokk sieht. Lasst mich durch die Augen von Skettis schauen.", sourceObjective = "Bringt das Auge des Reskkverstecks und das Auge des Shienorverstecks zu Rilak dem Erlösten im Unteren Viertel von Shattrath.", progress = "Ihr seid zurück, {class}. Welche Neuigkeiten bringt Ihr?", completion = "Euer Mut sollte belohnt werden. Die Wachen von Skettis rücken ihre Besitztümer nur ungern heraus.\n\nAber die Heldentaten der Vergangenheit sind nun nicht von Belang. Wir sollten uns lieber darum kümmern, dass dieser Heldenmut auch in der Zukunft weiter herrscht, denn Terokks Blick richtet sich gen Süden.\n\nDiese Augen sehen alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[10848] = { id = 10848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das untote Böse des Rhazeverstecks", description = "Das Rhazeversteck war eine besonders bösartige Kolonie von Skettis.\n\nTrotz der Auslöschung seiner Bewohner durch die Katastrophe von Auchindoun hielt Terokk seinen Einfluss auf die bösartigen Geister dort aufrecht. Reist nach Westen zum Rhazeversteck und tötet diese mörderischen Schufte. Ihr findet sie westlich des Schattengrabs, an der Grenze zwischen der Knochenwüste und den Wäldern von Terokkar.\n\nDies wird unser erster Schlag gegen Terokk und die Wächter von Skettis werden.", sourceObjective = "Tötet 4 Todeskrallengeister, 4 kreischende Geister und 2 Geistraben und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", completion = "Diese verderbten Geister haben es verdient zu sterben. Der Tod, den sie über alle anderen gebracht hätten, ist dafür Grund genug.\n\nEs besteht keine Hoffnung, dass wir die, die unter Terokks Einfluss stehen, erlösen können. Aber wir werden ihnen im Namen des Lichts ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10849] = { id = 10849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Kirrik", description = "Es waren noch andere Arakkoa an dem Verrat an Terokk beteiligt.\n\nKirrik erkannte in Terokk einen Scharlatan und keinen Propheten. Die einzige Prophezeiung, die Terokk vorausgesehen hat, war das Verderben, das auf seinen eigenen Wunsch heraufbeschworen wurde.\n\nEs war Kirrik, der uns mutig aus Skettis herausgeführt hat. Nach unserer Pilgerreise nach Shattrath ging Kirrik in alle anderen Kolonien, um nach Gleichgesinnten zu suchen.\n\nIn diesem Schreiben steht, was die Augen gesehen haben. Kirrik muss davon erfahren! Folgt der Straße nach Süden aus Shattrath hinaus zu der Knochenwüste und haltet nach der Karawane Ausschau.", sourceObjective = "Bringt Rilaks Schreiben zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste.", progress = "Ihr seid weit gereist und bringt mir Nachrichten.", completion = "Rilaks Geschichte ist grausam, Reisender. Wie Ihr am Zustand der Karawane sehen könnt, gibt es dieser Tage viel Leid und Düsterkeit in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10850] = { id = 10850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergas in einem Teufelsfeuermotor", progress = "Ihr findet die Öffnung, durch die der Teufelshäscher betankt wird.", completion = "Als Ihr den falschen Treibstoff einfüllt, beginnt der Motor des Teufelshäschers zu rumpeln und zu stottern." }
quests[10851] = { id = 10851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Totems meines Feindes", description = "Es gibt solche Wege, die Ahnen zu ehren, und es gibt andere Wege.\n\nDie Oger der Speerspießer tragen Totems bei sich, aber sie benutzten sie nicht, um ihre Ehrfurcht auszudrücken. Stattdessen wollen sie damit manipulieren und kontrollieren.\n\nWir sollten ihre Totems stehlen, denn sie sind unwürdig! Wir werden eine bessere Verwendung für sie finden.\n\nGeht zum Außenposten der Speerspießer im Westen, südwestlich des Messergrats. Erschlagt die Mystiker und Zermalmer der Speerspießer und nehmt ihnen die Totems ab!", sourceObjective = "Sammelt 5 Totems der Speerspießer.", progress = "Wart Ihr im Außenposten der Speerspießer und habt ihnen die Totems abgenommen?", completion = "Das sieht nach einer guten Sammlung aus. Wir sollten einen Weg finden können, sie respektvoll einzusetzen.\n\nIn der Tat habe ich sogar schon eine Idee!", sourceObjectiveStatus = "unverified-source-field" }
quests[10852] = { id = 10852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Freunde", description = "Wir haben uns hier niedergelassen, weil des Nachts ein paar Kerle kamen und Radau gemacht haben. Es war gruselig. Ich weiß nicht, wann wir weitergehen werden.\n\nEinige meiner Freunde fehlen. Ich habe keine Ahnung, wo sie sind. Ich fürchte, diese schauerlichen Vogelmänner haben sie mit nach Nordwesten genommen. Wahrscheinlich haben sie sie in Käfige eingesperrt und all so was. Es wäre toll, wenn Ihr sie finden könntet. Ich mache mir Sorgen um sie.", sourceObjective = "Ethan möchte, dass Ihr 12 seiner vermissten Freunde im Skithversteck findet und sie zu ihm bei der Flüchtlingskarawane zurückbringt.", completion = "Ihr habt all meine Freunde gefunden! Jetzt habe ich wieder jemanden, der mit mir spielt. Vielen Dank, Herr {name}.\n\nDa ich jetzt wieder andere Kinder zum Spielen habe, könnt Ihr ja eins meiner Spielzeuge haben. Dann habt Ihr auch etwas zum Spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10853] = { id = 10853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisteranrufung", description = "Die Geister der Netherdrachen im Singenden Bergrücken müssen befreit werden.\n\nDie Netherdrachen waren nicht immer Netherdrachen. Einst waren sie schwarze Drachen.\n\nDoch dann schwappte mit der Zerstörung dieser Welt eine Welle von Netherenergie über alles und veränderte die Eier der Drachlinge.\n\nSeitdem ist ihr eigenes Ich verzerrt. Wir müssen ihnen helfen, Frieden zu finden.\n\nDas erreicht Ihr, indem Ihr einen Drachen in der Nähe des Totems der Geisteranrufung tötet und ihm dann seine Seele nehmt.", sourceObjective = "Benutzt das Totem der Geisteranrufung, um 8 Geister eines geringen Netherdrachen zu sammeln.", progress = "Die Drachen des Singenden Bergrückens sind vielleicht eine Bedrohung für uns, doch sie sind majestätische Wesen.\n\nOder sie waren es zumindest. Ich hoffe, dass Ihr ihre Geister retten könnt.\n\nUnd falls Ihr noch mehr Totems brauchen solltet, habe ich noch ein paar über.", completion = "Ihr habt heute eine große Tat vollbracht, {class}. Die Geister der Drachen werden nun wieder singen können, denn sie sind frei. Und die Überreste ihrer Geister, die sie hinterlassen, dienen als mächtiges Heilmittel.\n\nHabt Ihr vielleicht Lust auf eine Reise in den Norden? Es gibt da eine Sache im Zusammenhang mit den Astralen, die mich brennend interessiert.\n\nIch fühle großen Schmerz aus dieser Richtung kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10854] = { id = 10854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht Neltharakus", description = "Nehmt diesen verzauberten Netherrankenkristall und begebt Euch zurück zur Festung des Drachenmals. Sucht nach den versklavten Drachen, wenn Ihr angekommen seid, und setzt die Magie des Kristalls frei. Meine eigenen Energien werden dafür sorgen, dass die Drachen ihre Fesseln abwerfen können. Wenn Ihr seht, dass ein Drache freigekommen ist, helft ihm schnell seinen Kerkermeister zu vernichten! Sie sind von der Gefangenschaft sicherlich noch geschwächt.\n\nLasst alle frei, die Ihr finden könnt und kehrt dann zu mir zurück, {name}!", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 5 versklavte Drachen der Netherschwingen befreit.", progress = "Verschwendet keine Zeit, wir haben viel zu tun!", completion = "<Neltharaku lacht.>\n\nDie Orcs müssen einen ganz schönen Schreck bekommen haben, als die Drachen sich plötzlich gegen sie gewendet haben. Gut gemacht, {name}. Vielleicht seid Ihr wirklich der Held unseres Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[10855] = { id = 10855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelshäscher, nein Danke!", description = "Ah ja, der Teufelshäscher! Das ist sicherlich die schrecklichste mechanische Erfindung der Legion. Und nicht weniger als drei dieser Abscheulichkeiten sind direkt auf die Sturmsäule gerichtet.\n\nZu unserem Glück sind sie noch nicht aktiviert. Das gibt uns die Möglichkeit, dieses Problem mit Sabotage anstatt mit roher Gewalt zu lösen.\n\nBeschafft Euch kondensiertes Nethergas von den Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt es in den Tank eines Teufelshäschers. Ich glaube, sein Motor wird sich nicht allzu sehr darüber freuen.", sourceObjective = "Beschafft Euch 5 Einheiten kondensiertes Nethergas von den Robogenieuren der Gan'arg in der Konstruktionsbasis: Vergessenheit, nordwestlich der Sturmsäule, und füllt sie in einen deaktivierten Teufelshäscher. Kehrt danach zu Netherpirscher Nauthis zurück.", completion = "Das sind ausgezeichnete Nachrichten, {name}. Jetzt, da wir wissen, wie wir mit ihnen zu verfahren haben, kann ich ein paar Leute anheuern, um die übrigen Häscher zu sabotieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10856] = { id = 10856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beste Verteidigung", description = "Mutige Industriesabotage wird uns leider nur bis zu einem gewissen Punkt weiterbringen, {name}. Genauso wie die Konstruktionsbasis: Vergessenheit als Produktionsstätte für die Teufelshäscher dient, ist die Konstruktionsbasis: Gehenna sowohl ein Stützpunkt für ihre Armee als auch der Ort, an dem sich die meisten Teleporter der Legion befinden.\n\nIch möchte, dass Ihr dorthin geht, und ihre Zahl tüchtig verringert. Bis heute müssen sie ein volles Regiment von Zornschaffern angesammelt haben. Das dürfen wir nicht zulassen!", sourceObjective = "Netherpirscher Nauthis möchte, dass Ihr 12 Zornschaffer in der Konstruktionsbasis: Gehenna nördlich der Sturmsäule vernichtet.", completion = "Gute Arbeit, {name}. Macht weiter so, dann werde ich beim Nexusprinzen ein gutes Wort für Euch einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10857] = { id = 10857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teleportiert das!", description = "So lustig es auch sein mag, Dämonen zu töten, so wenig hilft es uns, wenn die Legion weiterhin ihre Teleporter benutzen kann, um jeden Dämon, den wir töten, zu ersetzen.\n\nUnglücklicherweise habe ich gerade keinen hochwertigen Sprengstoff zur Hand... aber die Mo'arg, die die Teleporter warten, schon!\n\nNehmt diesen Stab... Ich habe seine Kraft so eingestellt, dass er die Gehirnströme der Mo'arg beeinflussen kann. Kehrt zur Konstruktionsbasis: Gehenna zurück und beeinflusst jeden Mo'arg, den Ihr seht. Viel Zeit bleibt Euch nicht, aber sie wird reichen, um ihre Sprengladungen bei den Teleportern in der Nähe zu benutzen.", sourceObjective = "Netherpirscher Nauthis möchte, dass Ihr den Stab der geistigen Beeinflussung bei den Mo'arg in der Konstruktionsbasis: Gehenna einsetzt und ihre Fähigkeit 'Teleporter sprengen' bei den drei Teleportern in der Konstruktionsbasis benutzt.", progress = "Ist es vollbracht? Sind die Teleporter außer Gefecht?", completion = "Dank Euch kann ich wieder etwas durchatmen, {name}. Das meine ich natürlich im übertragenen Sinne!\n\nIch nehme an, Ihr wollt nun eine Art Belohnung, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[10858] = { id = 10858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karynaku", description = "Ich schäme mich, Euch erneut um Hilfe zu bitten, {name}, aber Ihr seid die einzige Hoffnung meines Schwarms. Ohne mein Weibchen stirbt die Brut der Netherschwingen vielleicht ganz aus!\n\nMacht Euch auf den Weg zur Spitze der Festung des Drachenmals und findet Karynaku.\n\nWir werden über Euch fliegen. Sollte sich ein Loch in ihrer Verteidigung auftun, wird die geballte Macht der Netherschwingen Euch zu Hilfe eilen.", sourceObjective = "Sucht nach Karynaku in der Festung des Drachenmals.", completion = "Es sind die Ketten. Sie berauben mich meiner Macht. Der einzige Ausweg ist, den Schlüssel von Zuluhed zu beschaffen und mich loszuketten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10859] = { id = 10859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt die Kugeln", description = "Die Astralen der Razaani haben merkwürdige Geräte, aus denen kleine, rosafarbene schwebende Lichtkugeln herauskommen. Sie erinnern mich an Seelen.\n\nMan darf sie nicht mit den großen gelben Kugeln verwechseln, die sich aus den Astralen lösen, wenn sie sterben. Diese hier sind ganz anders.\n\nIch möchte, dass Ihr nach Norden zu Razaans Landeplatz geht und ein paar Totems aufstellt, die die rosafarbenen Lichtkugeln anziehen.\n\nBringt sie zu mir zurück, damit ich genau herausfinden kann, aus was sie bestehen.", sourceObjective = "Benutzt das Kugelfängertotem, um 15 Lichtkugeln der Razaani zu sammeln.", progress = "Habt Ihr alle Lichtkugeln der Razaani, die ich brauche, gesammelt?", completion = "Etwas fühlt sich hier falsch an.\n\nBitte, {name}, reicht mir das Totem. Ich muss diese Kugeln untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10860] = { id = 10860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckerbissen der Mok'Nathal", description = "Seid Ihr hungrig, {race}? Der große Geist hilft denen, die sich selbst helfen. Wenn Ihr Euch ein Essen verdienen wollt, schlage ich vor, dass Ihr zuhört, denn Braagor da drüben wird Euch nichts umsonst geben, zumindest nichts, was so schmackhaft wäre.\n\nDie Raptoren und Schuppenflügel des Messergrats und der Schuppenflügelbank haben alles, was man für zwei der schmackhaftesten Gerichte, die Ihr je zu essen bekommen werdet, braucht. Bringt mir ihre Raptorenrippchen und das Schlangenfleisch, und ich werde Euch beide zubereiten.\n\nIch kann Euch auch beibringen, sie selbst zu kochen, wenn Ihr in Eile seid.", sourceObjective = "Sammelt 3 Raptorenrippchen und 3 Stück Schlangenfleisch.", progress = "Habt Ihr alle Zutaten schon? Darüber zu reden hat mir das Wasser im Munde zusammenlaufen lassen!", completion = "Mmm, ich kann sie schon schmecken! Schnell, reicht mir die Zutaten... Ich werde sie rasch klein würfeln und dann ab damit aufs Feuer!\n\nZu Eurem Glück hält sich das Zeug lange, und ich meine damit sehr lange! So, nehmt dies. Und da Ihr so freundlich wart, meine Speisekammer aufzufüllen, gebe ich Euch die Rezepte gleich noch dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[10861] = { id = 10861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präventivschlag gegen das Lithicversteck", description = "In der verachtungswürdigen Kolonie im Südwesten, die als Lithicversteck bekannt ist, versuchen die Diener Terokks ihre geflügelten Brüder schon vor dem Schlüpfen zu verderben. Die schwarzen Zauberer von Lithic belegen die Eier mit einem schattenhaften Fluch. Wenn die Küken schlüpfen, sind sie bereits willenlose Diener Terokks.\n\nReist ins Lithicversteck und zerbrecht die Eier, bevor der Fluch wirken kann. Sogar wenn es dazu schon zu spät ist, könnt Ihr die verderbten Eier vernichten.\n\nDenkt daran, in der Dunkelheit strahlt das Licht noch heller.", sourceObjective = "Zerbrecht die verfluchten Eier im Lithicversteck. Erlöst 3 Jungtiere und tötet 3 bösartige Jungtiere. Kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", progress = "Habt Ihr Eure Aufgabe erledigt? Vernichtet das Böse, bevor es zu spät ist!", completion = "Es ist eine grausame Aufgabe, Jungtiere zu quälen, und doch wäre es unverzeihlich, das wachsende Böse zu ignorieren. Ihr habt gute Arbeit geleistet. A'dals Gunst leuchtet auf Euch herab.", sourceObjectiveStatus = "unverified-source-field" }
quests[10862] = { id = 10862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslieferung an die Horde", description = "Die feigen Arakkoa greifen uns täglich an. Sie lauern unseren Jägern auf und plündern ab und an sogar innerhalb unserer Stadtmauern! Wir töten sie, wenn wir können, aber ihre Magie ist stark und sie schaffen es oft, unseren Truppen zu entkommen.\n\nIch habe erfahren, dass einige Arakkoa der Horde gegenüber freundlich gesonnen sein sollen. Sie leben in Shattrath im Nordwesten. Ihr Anführer nennt sich Rilak der Erlöste. Sucht im Unteren Viertel nach ihm und fordert ihn auf, sich auszuliefern.", sourceObjective = "Rokag möchte, dass Ihr Rilak den Erlösten im Unteren Viertel von Shattrath aufsucht und von ihm fordert, dass er und sein Volk sich der Horde ausliefern.", completion = "Euer Volk ist wütend, aber ich kann nicht viel dagegen tun. Einige von uns wurden von der Macht der Naaru berührt und für alle Zeiten verändert. Doch diejenigen von uns, die in der Wildnis leben, sind noch immer so, wie wir damals waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10863] = { id = 10863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Arakkoa", description = "Hier an der Front müssen wir uns Tag für Tag mit den Arakkoa herumschlagen. Sie greifen uns an, wenn es ihnen gerade passt, plündern unsere Vorräte und erschlagen unsere Späher.\n\nUnd doch wissen wir nur wenig über diese rätselhaften Kreaturen. Ich habe Informationen erhalten, denen zufolge in Shattrath im Nordwesten einige Arakkoa leben sollen, die nicht so feindselig sind und vielleicht die Geheimnisse ihres Volks mit uns zu teilen bereit sind.\n\nRilak der Erlöste ist ihr Anführer. Er lebt im Norden des Unteren Viertels.", sourceObjective = "Lady Dena Kennedy möchte, dass Ihr Rilak den Erlösten im Unteren Viertel von Shattrath aufsucht und herausfindet, welche Geheimnisse der Arakkoa mit Euch teilen wird.", completion = "Es war sehr weise von Euch, mich aufzusuchen. Es gibt vieles, was ich Euch zeigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10864] = { id = 10864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Last auf der Seele", description = "Ich habe ein Gerät, mit dem man Teufelsmagie analysieren kann, der dämonische Seher. Ich würde Euch den Seher ja benutzen lassen, aber zunächst müsst Ihr ihn... besänftigen. Ihr müsst wissen, dass innerhalb des Sehers ein Wesen von höchster Intelligenz steckt, das einige, sagen wir, exzentrische Bedürfnisse hat.\n\nUm den Seher zu besänftigen, müsst Ihr Orcs töten, insbesondere die Orcs der Zerschmetterten Hand. Der Seher verlangt ihre Seelen.\n\nKehrt zu mir zurück, wenn Ihr die Seelen geerntet habt. Ihr findet die Orcs nördlich, südlich und um die Höllenfeuerzitadelle herum.", sourceObjective = "Tötet 20 Orcs der Zerschmetterten Hand und kehrt danach zu Apotheker Antonivich in Thrallmar zurück.", completion = "Gut gemacht, {name}. Eure Seele ist mit vielen Toden belastet... und der dämonische Seher wird nun seine Pflicht für Euch erfüllen.\n\nWollen wir hoffen, dass Ihr für das Folgende gewappnet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10865] = { id = 10865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informiert Leoroxx!", description = "Schnell, Ihr müsst Leoroxx über die Geschehnisse bei Razaans Landeplatz informieren.\n\nDiese Kugeln wurden aus Seelen geschaffen, einige davon Seelen der Mok'Nathal!", sourceObjective = "Sprecht mit Leoroxx darüber, was die Astralen der Razaani treiben. Ihr findet ihn im Dorf der Mok'Nathal im Schergrat.", completion = "Ist das, was Ihr da sagt, überhaupt möglich? Was sage ich da? Natürlich ist es das, wenn der Geistrufer davon überzeugt ist.\n\nErinnert Ihr Euch noch, als ich sagte, dass wir vielleicht wieder Eure Hilfe brauchen würden? Wie es scheint, kann ich in die Zukunft sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10866] = { id = 10866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed der Geschlagene", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", sourceObjective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", progress = "<Karynaku brüllt.>", completion = "Ich bin frei! Ihr habt uns gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10867] = { id = 10867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann nur eine Antwort geben", description = "Es kann nur eine Antwort auf diese... diese SCHÄNDUNG der Seelen unserer Vorfahren geben!\n\n{name}, wenn Ihr uns helfen wollt, die Seelen unserer verehrten Toten zu ihrem richtigen Platz zurück zu bringen, dann kehrt zu Razaans Landeplatz zurück.\n\nGeht dorthin zurück und tötet die Razaani bis ihr Anführer, Nexusprinz Razaan, sein feiges Gesicht zeigt. Tötet ihn, beschafft Euch die Seelen zurück und übergebt sie Geistrufer Dohgar!", sourceObjective = "Beschafft Euch die Seelensammlung.", progress = "Habt Ihr es getan? Sind die Seelen unserer Vorfahren sicher vom Bösen der Astralen?", completion = "Es ist gut, dass der Abschaum der Astralen und ihr Anführer tot sind. Ich wünsche ihren Brüdern tausend Plagen auf den Hals!\n\nIhr sollt für Eure Taten im Namen aller Mok'Nathal belohnt werden, {name}! Ihr seid wirklich ein Held für uns!\n\nLasst uns nun die Seelen unserer Vorfahren dem reinigenden Feuer übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10868] = { id = 10868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegspfad der Arakkoa", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt, um zu entkommen, bevor wir losstürmen und ihnen in gleicher Zahl entgegentreten konnten. Sie benutzen ihre Beschwörungskreise, um ihre Krieger vor dem sicheren Tod zu retten, aber wenn wir ihr Zuhause angreifen, können sie uns nicht entkommen. Das Reskkversteck und das Shienorversteck liegen im Norden und Nordosten.\n\nFindet die Nester der Arakkoa und tötet so viele, wie Ihr könnt.", sourceObjective = "Beraterin Faila bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihr in der Steinbrecherfeste zurück.", completion = "Gut gemacht, {class}. Die Arakkoa haben gelernt, die Macht der Horde zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10869] = { id = 10869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herde ausdünnen", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt, um zu entkommen, bevor wir unsere Soldaten losschicken konnten.\n\nDas Reskkversteck und das Shienorversteck liegen im Norden und Nordwesten. Sucht diese Nester der Arakkoa und tötet so viele, wie Ihr könnt. Vielleicht fürchten sie uns nicht, aber wir können ihre Zahl dennoch verringern!", sourceObjective = "Leutnant Kieshammer bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihm in Allerias Feste zurück.", completion = "Gut gemacht, {class}. Die Arakkoa haben gelernt, die Macht der Allianz zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10870] = { id = 10870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Netherschwingen", description = "Erlaubt mir, Euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", sourceObjective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10871] = { id = 10871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Netherschwingen", description = "Erlaubt mir, Euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", sourceObjective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10872] = { id = 10872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed der Geschlagene", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", sourceObjective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", completion = "Ich bin frei! Ihr habt uns gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10873] = { id = 10873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Nacht verschleppt", description = "Unser kleiner Außenposten wird ständig angegriffen. Vor ein paar Nächten haben die Spinnen des Netherweberkamms, der am südöstlichen Ende der Knochenwüste liegt, unser Lager überfallen. Sie haben viele von uns vergiftet, in ihre Netze gewickelt und fort getragen. Einige unserer Krieger haben zu den Waffen gegriffen und sind den Spinnen todesmutig in die finstere Nacht gefolgt.\n\nWir haben weder die Gefangenen noch die Krieger seit diesem Tag wieder gesehen. Wir hoffen, dass sie noch am Leben sind. Vielleicht halten die Spinnen sie gefangen? Wir sind nur so wenige. Könnt Ihr nach unseren Leuten suchen?", sourceObjective = "Späher Navrin möchte, dass Ihr zum Netherweberkamm reist und 6 eingesponnene Verteidiger der Sha'tar befreit. Kehrt danach zu Navrin ins Basislager der Sha'tari zurück.", completion = "Ihr habt so viele gerettet. Ich habe nicht geglaubt, dass wir sie je wieder sehen würden. Wir können Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10874] = { id = 10874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signalfeuer des Shalasverstecks", description = "Über der Knochenwüste im Osten wirft Skettis, der lange Arm Terokks, bedrohlich seine Schatten. Am Fuße von Skettis liegt das Shalasversteck, Terokks vortrefflichste Kolonie. Von diesem Stützpunkt aus führen Terokks Diener Krieg gegen das Licht.\n\nDie Unholde der Shalas kommunizieren über ein komplexes System aus magischen Signalfeuern mit ihrem Meister. Reist nach Osten, {race}, und löscht die Feuer. Sobald das Shalasversteck zum Schweigen gebracht wurde, können wir den Fall von Skettis planen.\n\nAber ich greife mir selbst vor.", sourceObjective = "Kirrik der Erwachte bei der Flüchtlingskarawane möchte, dass Ihr die vier Signalfeuer des Shalasverstecks löscht.", completion = "Wir haben gesehen, wie der verfluchte Rauch aufgestiegen ist. Ihr seid außergewöhnlich mutig, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10875] = { id = 10875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Nazgrel", description = "{name}, während Eures Auftrags mit dem dämonischen Seher habe ich einen Bericht über Eure Taten gegen die Höllenorcs geschickt. Nazgrel, unser berühmter Anführer in Thrallmar, möchte mit Euch sprechen. Ich glaube, er hat einen blutigen Auftrag für Euch...", sourceObjective = "Sprecht mit Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", completion = "Es ist schön, von Euren Schachzügen gegen die Höllenorcs zu erfahren, {name}. Die Apotheker haben viel Zeit und viel Mühe aufgewendet, um hinter den Grund der Verderbnis zu kommen, und auch wenn diese Informationen sicher unersetzlich sind... schreit mein Orcblut danach, diesen Verrätern einen anständigen Schlag zu verpassen!\n\nHört genau zu, wenn ich Euch Eure Aufgabe erkläre...", sourceObjectiveStatus = "unverified-source-field" }
quests[10876] = { id = 10876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Fuße der Zitadelle", description = "Truppenkommandant Gorax trainiert die Hauptmänner am Fuß der Höllenfeuerzitadelle und drillt sie, bis sie so scharf wie Rasierklingen sind. Ihr müsst ihn töten, {name}. Sein Verlust wäre ein großer Schaden für die Höllenorcs.\n\nDas ist jedoch nicht alles, was Ihr tun müsst.\n\nNehmt dieses Banner. Platziert es auf Gorax' Leichnam. Wenn auch nur ein Tropfen echtes Orcblut in seinem Körper steckt, muss sein Kommandant, die Hand von Kargath, Eure Herausforderung annehmen!\n\nSein Kopf, der Kopf der Hand von Kargath, ist das, was ich begehre.", sourceObjective = "Tötet Truppenkommandant Gorax, platziert die Herausforderung der Horde auf seinem Leichnam. Tötet danach die Hand von Kargath und bringt den Kopf der Hand von Kargath zu Nazgrel in Thrallmar.", progress = "Habt Ihr Euch der Hand von Kargath gestellt, {name}?", completion = "Ihr habt eine große Tat geleistet, {name}. Die Höllenorcs sind eine Schande für alle wahren Orcs. Wenn wir eine Angst haben, so ist es die, erneut einer dämonischen Verderbnis zu verfallen. Unser Krieg gegen die Höllenorcs ist also mehr als nur eine Schlacht gegen schlimme Feinde, es ist eine Schlacht in uns selbst.\n\nUnd mit einer Stärke, wie Ihr sie heute bewiesen habt, werden wir diese Schlacht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10877] = { id = 10877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schreckensrelikt", description = "Vor langer Zeit machte sich eine Karawane auf den Weg nach Auchindoun mit der Mission, ein Schreckensrelikt aus den uralten Gräbern unter der Stadt der Toten zu bergen. Sie sind geflohen, aber das Relikt sollte ihr Untergang sein. Das Relikt ist böse und ruft Böses herbei, wenn es berührt wird. Ihre Karawane wurde irgendwo im Osten vernichtet.\n\nDieses finstere Artefakt ist der Schlüssel zu meinem schrecklichen Plan, Teribus den Verfluchten zu töten, eine Kreatur, die über der Knochenwüste ihre Kreise zieht. Wenn Ihr wünscht, könnt Ihr mir helfen, aber Euer Leben und Eure Seele stehen dabei auf dem Spiel.", sourceObjective = "Oakun möchte, dass Ihr nach Osten zur Herrenlosen Karawane reist und das Schreckensrelikt besorgt. Kehrt zu Oakun zurück, wenn Eure Aufgabe erledigt ist.", progress = "Habt Ihr das Schreckensrelikt? Wir müssen es bekommen.", completion = "Es ist unglaublich, dass Ihr es geschafft habt. Das Schreckensrelikt ist viel mächtiger, als ich befürchtet hatte. Nur ein starker Held hätte die lange Rückreise mit so einem blasphemischen Gegenstand überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10878] = { id = 10878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevor die Dunkelheit sich senkt", description = "Nachdem unsere Karawane einem Angriff von Kultisten der Kabale des Schattenrats zum Opfer gefallen ist, wurden Späher auf der Suche nach Hilfe nach Shattrath geschickt. Die Wachen denken, wir sind vorerst sicher, aber sie unterschätzen diese Verrückten.\n\nIch freue mich jedenfalls nicht darauf, mir meine Kehle von irgendeinem Initianden der Kabale mitten in der Nacht durchschneiden zu lassen. Tut uns allen einen Gefallen und greift sie an, bevor sie es tun.\n\nIhr findet unsere Angreifer südlich von hier, am nördlichen Eingang von Auchindoun.", sourceObjective = "Mekeda bei der Flüchtlingskarawane möchte, dass Ihr 8 Scharmützler der Kabale, 4 Zauberwirker der Kabale und 2 Initianden der Kabale tötet.", completion = "Vorerst kann ich erleichtert durchatmen, {name}. Der Schattenrat wird sich bis auf weiteres zurückhalten.\n\nSie sind Mörder und Feiglinge. Eure Zurschaustellung von Mut wird sie einschüchtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10879] = { id = 10879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive aus Skettis", description = "Skettis hat uns den Krieg erklärt! Habt Ihr genug Kraft für die Verteidigung Shattraths gesammelt?\n\nHaltet die Angreifer auf!", sourceObjective = "Haltet die Angreifer auf und sprecht mit Rilak den Erlösten.", completion = "Ich ziehe meinen Hut vor Euren Kampfkünsten, {class}. Ihr habt Euch als wahrer Verteidiger des Lichts bewiesen. Möge A'dals Segen in Euren dunkelsten Stunden auf Euch ruhen.\n\nDoch seht zum fernen Horizont. Dunkle Wolken ziehen unheilvoll über Skettis herauf. Sicher plant Terokk schon seinen nächsten Schachzug. Für heute ist Shattrath gerettet. Doch wer weiß schon, welch Verderben der nächste Tag über uns alle bringen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10880] = { id = 10880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle der Kabale", description = "Die Botschaft trägt ein dunkles Siegel. Auch wenn Euch die Sprache bekannt vorkommt, scheint der Text verschlüsselt zu sein.\n\nVielleicht weiß jemand bei der Flüchtlingskarawane etwas darüber.", sourceObjective = "Bringt die Befehle der Kabale zu Mekeda bei der Flüchtlingskarawane in der Knochenwüste.", progress = "Wollt Ihr mir etwas zeigen, {name}?", completion = "Ah, ja... dieser Text wurde in einer einfachen Form der Geheimschrift der Schatten geschrieben. Mein Wissen darüber ist nicht perfekt, aber es sollte ausreichen, um sie zu übersetzen.\n\nMan kann viel von den zwielichtigen Gestalten lernen, wenn man unter den Ausgestoßenen und Flüchtlingen im Unteren Viertel lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10881] = { id = 10881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengrab", description = "Viele glauben, dass der Schattenrat die Explosion, die Auchindoun in tausend Stücke gerissen hat, verursacht hat. Gerüchten zufolge sollen sie im Inneren ein großes Übel erweckt haben.\n\nWenn das stimmt, muss dieses Böse sich gegen sie gewandt haben. Laut diesen Befehlen flieht ein Teil des Schattenrats aus Auchindoun. Sie benutzen das Schattengrab, um mächtige Artefakte aus Auchindoun zu lagern.\n\nDrei dieser Artefakte sind heilig, denn sie gehörten den mächtigen Patriarchen Arunen, K'alen und Atalor. Ich muss Euch bitten, sie wieder zu holen.", sourceObjective = "Geht in das Schattengrab westlich der Flüchtlingskarawane und beschafft Euch das Tuch des Arunen, den Hammer des K'alen und die Rolle des Atalor. Kehrt danach zu Mekeda bei der Flüchtlingskarawane zurück.", progress = "Habt Ihr die Relikte, {name}? Wir können nicht zulassen, dass der Schattenrat sie für seine dunklen Zwecke einsetzt.", completion = "Das Licht hat mich vielleicht vergessen, aber ich habe das Licht nicht vergessen. Diese Relikte waren meinem Volk einst sehr heilig.\n\nDem Schattenrat zu erlauben, sie für Böses einzusetzen ist... undenkbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10882] = { id = 10882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herold der Verdammnis", description = "<Ein Missklang ertönt in A'dals 'Stimme'.>\n\nPrinz Kael'thas hat seine Wärter schlampig ausgewählt, und nun brechen die Wesenheiten, die in der Arkatraz eingesperrt waren, aus.\n\nBesonders eine davon, ein Diener der Alten Götter, der als Herold Horizontiss bekannt ist, versucht, die Vision seines Meisters von der Eroberung aller Welten in diesem Universum in die Tat umzusetzen.\n\n{name}, Ihr dürft nicht zulassen, dass er entkommt. Kehrt zur Festung der Stürme zurück und begebt Euch in die Arkatraz. Tötet Herold Horizontiss, bevor es zu spät ist!", sourceObjective = "Ihr wurdet beauftragt, zur Arkatraz in der Festung der Stürme zu reisen und Herold Horizontiss zu töten. Kehrt danach zu A'dal auf der Terrasse des Lichts in Shattrath zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10883] = { id = 10883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel der Stürme", description = "Ihr habt Euch in großen Taten bewiesen, {name}. Eure Entdeckung der Litanei der Verdammnis und Kael'thas' Rolle dabei sind für unsere Sache von äußerster Wichtigkeit. Sollte Kael'thas die Litanei benutzen, würde der kleine Rest, der noch von dieser Welt übrig ist, in sich zusammenfallen.\n\nA'dal ist davon überzeugt, dass Kael aufgehalten werden muss und ist nun auf der Suche nach Abenteurern, die sich seinen Prüfungen unterziehen möchten. Die Naaru werden denjenigen, die ihre Stärke beweisen, ihre Gunst gewähren.\n\n<Khadgar nickt.>\n\nA'dal erwartet Euch...", sourceObjective = "Sprecht mit A'dal in Shattrath.", completion = "Die Festung der Stürme ist eine Erfindung der Naaru, Sterblicher. Zutritt zu der Festung zu gewähren lag schon immer alleine im Ermessen der Naaru. Eine Rückkehr zur Festung der Stürme erschien uns jedoch unnötig. Vielleicht mag das für ein sterbliches Volk wie Stolz aussehen, doch wir Naaru halten nur wenig von solchen Dingen.\n\nWir gehen nun, weil wir es müssen. Kael'thas darf die Litanei der Verdammnis niemals vorlesen.\n\nAuch wenn der Weg offen steht, so würde sich nur ein Narr unerprobt hineinwagen. Unterschätzt nicht den Zweck der Prüfungen, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[10884] = { id = 10884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Erbarmen", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle werden drei Leute Eures Volkes von dem erbarmungslosen Kargath Messerfaust gefangen gehalten. Er hat vor, sie als Zeichen seiner Männlichkeit und Stärke hinzurichten. Ihr müsst diese Gefangenen retten, bevor eine solche Grausamkeit geschehen kann. Bringt mir die unbenutzte Axt des Henkers als Beweis Eurer Tat. Es darf kein einziger Tropfen Blut an der Klinge sein!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr die unbenutzte Axt des Henkers aus den Zerschmetterten Hallen der Höllenfeuerzitadelle besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, {name}. Ihr habt die Prüfung des Erbarmens abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10885] = { id = 10885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Stärke", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nDie Prüfung der Stärke besteht aus zwei Teilen. Ihr müsst den Anführer der Dampfkammern des Echsenkessels, Kriegsherr Kalithresh, töten und mir seinen Dreizack bringen. Außerdem müsst Ihr das außerdimensionale Wesen Murmur im Schattenlabyrinth in Auchindoun erlegen und mir seine Essenz bringen.\n\nWenn Ihr dies geschafft habt, habt Ihr die Prüfung der Stärke bestanden.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Kalithreshs Dreizack und Murmurs Essenz besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, {name}. Ihr habt die Prüfung der Stärke abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10886] = { id = 10886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Zuverlässigkeit", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nAuf unseren Reisen haben wir viele gefährliche Wesen getroffen. Einige dieser Wesen wurden eingefangen und werden nun an Bord der Arkatraz in der Festung der Stürme gefangen gehalten.\n\nEiner der Gefangenen ist jedoch Opfer eines unglücklichen Zufalls. Er war zur falschen Zeit als blinder Passagier auf dem falschen Schiff der Naaru unterwegs.\n\nReist zur Arkatraz und rettet den Gnom Millhaus Manasturm. Stellt sicher, dass er überlebt.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Millhaus Manasturm aus der Arkatraz in der Festung der Stürme rettet.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", completion = "Gut gemacht, {name}. Ihr habt die Prüfung der Zuverlässigkeit abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10887] = { id = 10887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus dem Grab", description = "Ich weiß Eure Hilfe zu schätzen, {name}. Ich war mir sicher, dass ich sterben würde.\n\nLasst uns schnell von hier verschwinden. Bald werden uns noch mehr Kultisten auf den Fersen sein.", sourceObjective = "Helft Akuno zur Flüchtlingskarawane zu gelangen. Sprecht danach mit Mekeda.", completion = "Ihr habt Akuno, meinen geschätzten Freund, errettet. Dafür stehe ich in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10888] = { id = 10888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Magtheridon", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10889] = { id = 10889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Shattrath", description = "Auch wenn Eure Taten sehr mutig waren, wird Terokk sicher nicht lange auf seine Rache warten lassen.\n\nGeht schnell nach Shattrath! Verständigt Rilak!", sourceObjective = "Reist nach Shattrath und Sprecht mit Rilak den Erlösten im Unteren Viertel.", completion = "Die Wachen von Skettis werden langsam unruhig. Shattrath steckt in Schwierigkeiten. Wir werden Terokks Rache sicher eiskalt zu schmecken bekommen.\n\nStellt schnell eine Verteidigung auf die Beine! Sprecht mit Verteidiger Grashna und lasst ihn wissen, dass Ihr bereit seid, die Waffen gegen unsere Angreifer zu erheben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10891] = { id = 10891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenrüstung", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", sourceObjective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[10892] = { id = 10892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenrüstung", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", sourceObjective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[10893] = { id = 10893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langschweif ist der springende Punkt", description = "Da die Wyrmkultisten der Pechschwingen sich im Tunnel sammeln, sehen wir uns gezwungen, der Lage Herr zu werden. Ehrlich gesagt sind sie deutlich in der Überzahl.\n\nAuch wenn wir bisher diejenigen, die uns zu nahe gekommen sind, zurückhalten konnten, wären wir einem ernsthaften Angriff von ihnen nicht gewachsen.\n\nDie Lage erfordert, dass jemand sich bis an das andere Ende des Tunnels durchkämpft und ihre Anführerin, Draaca Langschweif, unschädlich macht. Habt Ihr Lust auf ein wenig Spaß?", sourceObjective = "Tötet Draaca Langschweif, die Anführerin der Wyrmkultisten im Tunnel des Wyrmschädels.", completion = "Nun, da Draaca unschädlich gemacht wurde, sollten wir in der Lage sein, unseren Vorteil aus der Situation zu ziehen. Sie werden sich jetzt untereinander darum streiten, wer die Leitung übernehmen soll, und das wird uns viel Druck nehmen.\n\nEs sei denn der Aufseher aus dieser Einladung, die Ihr mir gegeben habt, nimmt ihren Platz ein.\n\nWir sollten sicherstellen, dass das niemals passieren wird!", sourceObjectiveStatus = "unverified-source-field" }
